import { StatefulSmartContract, ByteString } from 'runar-lang';

export class DataOutputTest extends StatefulSmartContract {
    count: bigint;
    constructor(count: bigint) { super(count); this.count = count; }

    public publish(payload: ByteString) {
        this.count = this.count + 1n;
        this.addDataOutput(0n, payload);
    }
}

import { StatefulSmartContract } from 'runar-lang';

export class RawOutputTest extends StatefulSmartContract {
    count: bigint;
    constructor(count: bigint) { super(count); this.count = count; }

    public sendToScript(scriptBytes: ByteString) {
        this.addRawOutput(1000n, scriptBytes);
        this.count = this.count + 1n;
        this.addOutput(0n, this.count);
    }
}

import { StatefulSmartContract, PubKey, Sig, assert, checkSig } from 'runar-lang';

/**
 * AllReadonlyCleanstack — regression fixture for issue #44.
 *
 * A {@link StatefulSmartContract} subclass with ZERO mutable fields (only a
 * readonly `owner`) plus a readonly-field-binding in a terminal method. The
 * `const ownerCopy = this.owner` binding force-embeds the readonly field onto
 * the stack; it is not consumed by the terminal `checkSig` assertion, so it
 * leaves an excess stack item below the top-of-stack boolean.
 *
 * Bitcoin Script's CLEANSTACK rule requires exactly one item on the stack at
 * end-of-script. Before the fix, `cleanupExcessStack()` was gated behind a
 * `hasDeserializeState` check — which is never true for an all-readonly
 * stateful contract — so the leftover item survived and the spend was rejected
 * on mainnet with "Script did not clean its stack". The fix runs
 * `cleanupExcessStack()` for every public method (it is a no-op when the stack
 * is already balanced), emitting the trailing `OP_NIP` that balances the stack.
 */
class AllReadonlyCleanstack extends StatefulSmartContract {
  readonly owner: PubKey;

  constructor(owner: PubKey) {
    super(owner);
    this.owner = owner;
  }

  public claim(sig: Sig): void {
    const ownerCopy = this.owner;
    assert(checkSig(sig, this.owner));
  }
}

import { StatefulSmartContract, assert, checkSig } from 'runar-lang';
import type { ByteString, PubKey, Sig } from 'runar-lang';

/**
 * AnnotatedVault — N-044 conformance fixture: a mutable variable-length
 * ByteString state field (`memo`) BEFORE a mutable PubKey (`owner`).
 *
 * Anyone may replace the memo; only the owner may withdraw. The on-chain state
 * reader decodes `memo`'s PUSHDATA length to find where `owner` starts, so that
 * length must be read as the UNSIGNED integer the writer meant. Before N-044 a
 * 128-byte memo (framed `4c 80`) read as length 0 and the memo's first 33 bytes
 * became `owner`: a stranger who annotated a memo beginning with their own
 * pubkey could then withdraw.
 */
class AnnotatedVault extends StatefulSmartContract {
  memo: ByteString;
  owner: PubKey;
  balance: bigint;

  constructor(memo: ByteString, owner: PubKey, balance: bigint) {
    super(memo, owner, balance);
    this.memo = memo;
    this.owner = owner;
    this.balance = balance;
  }

  /** Replace the memo. Anyone can call this method. */
  public annotate(nextMemo: ByteString) {
    this.memo = nextMemo;
  }

  /** Only the owner may spend. */
  public withdraw(sig: Sig) {
    assert(checkSig(sig, this.owner));
  }
}

import { SmartContract, assert } from 'runar-lang';

class Arithmetic extends SmartContract {
  readonly target: bigint;

  constructor(target: bigint) {
    super(target);
    this.target = target;
  }

  public verify(a: bigint, b: bigint): void {
    const sum: bigint = a + b;
    const diff: bigint = a - b;
    const prod: bigint = a * b;
    const quot: bigint = a / b;
    const result: bigint = sum + diff + prod + quot;
    assert(result === this.target);
  }
}

import { UnsafeSmartContract, asm } from 'runar-lang';

/**
 * Anyone — minimal `asm` raw-script contract.
 *
 * Compiles to a single byte (`0x51`, OP_1) locking script that anyone can
 * spend. Exists to exercise the `asm({...})` intrinsic and
 * `UnsafeSmartContract` parent class across all 9 source formats.
 */
class Anyone extends UnsafeSmartContract {
  constructor() {
    super();
  }

  public unlock() {
    asm({ body: '51', in_arity: 0, out_arity: 1 });
  }
}

import {
  StatefulSmartContract,
  assert,
  checkSig,
  continuationAmount,
  extractAmount,
  extractLocktime,
  extractSequence,
} from 'runar-lang';
import type { PubKey, Sig } from 'runar-lang';

/**
 * On-chain English auction contract.
 *
 * Bidders compete by submitting progressively higher bids until a block-height
 * deadline. After the deadline, only the auctioneer can close the auction.
 *
 * **Lifecycle:**
 * 1. The auctioneer deploys the contract with themselves as the initial highest
 *    bidder, a highest bid of 0, and a block-height deadline.
 * 2. Anyone calls {@link bid} to outbid the current leader. Each successful bid
 *    creates a new UTXO carrying the updated state. Bidding stays open for as
 *    long as that UTXO is unspent — see **Time enforcement** below.
 * 3. Once the deadline has passed, the auctioneer calls {@link close} to
 *    finalize the auction and spend the UTXO.
 *
 * **Stateful mechanics:**
 * Extends {@link StatefulSmartContract}. The compiler auto-injects
 * `checkPreimage` at method entry and a state-continuation output at method
 * exit for state-mutating methods. Each continuation UTXO encodes state as:
 * `OP_RETURN <auctioneer> <highestBidder> <highestBid> <deadline>`
 *
 * **Time enforcement — read this before copying the pattern:**
 * `nLockTime` is chosen by the *spender* and enforced by consensus as a
 * NOT-BEFORE: the transaction becomes mineable once the chain has reached it.
 * Nothing about it bounds the chain from above. A script can therefore assert
 * "not before T" and can NEVER assert "before T" — a bidder at height T+1
 * simply stamps a stale `nLockTime` of T-1 and the node mines it happily.
 *
 * So {@link bid} carries no deadline check at all: bidding is open until the
 * auctioneer closes. {@link close} uses the direction that does work,
 * `nLockTime >= deadline`, paired with `extractSequence !== 0xffffffff`.
 * That second assert is load-bearing, not decoration: consensus ignores
 * `nLockTime` entirely when every input is final, so without it the auctioneer
 * could stamp `nLockTime = deadline` on an all-final transaction and close at
 * any height, before anyone had a chance to bid.
 *
 * A trustless "bids only before T" window needs a time source the contract can
 * read as state — an oracle or a tick — not the spending transaction's own
 * locktime. v1 does not ship one.
 */
class Auction extends StatefulSmartContract {
  /** The public key of the auction creator. Immutable — baked into the script at deploy time. */
  readonly auctioneer: PubKey;
  /** Public key of the current highest bidder. Mutable state that persists across transactions. */
  highestBidder: PubKey;
  /** Current highest bid amount in satoshis. Mutable state that persists across transactions. */
  highestBid: bigint;
  /** Block height after which no more bids are accepted. Immutable — baked into the script. */
  readonly deadline: bigint;

  constructor(auctioneer: PubKey, highestBidder: PubKey, highestBid: bigint, deadline: bigint) {
    super(auctioneer, highestBidder, highestBid, deadline);
    this.auctioneer = auctioneer;
    this.highestBidder = highestBidder;
    this.highestBid = highestBid;
    this.deadline = deadline;
  }

  /**
   * Submit a new bid that outbids the current highest.
   *
   * State-mutating: the compiler auto-injects `checkPreimage` at entry and
   * appends a state-continuation output at exit, creating a new UTXO with
   * the updated `highestBidder` and `highestBid`.
   *
   * There is deliberately no deadline check here — see **Time enforcement** on
   * the class. A bid lands whenever the contract's UTXO is still unspent.
   *
   * @param sig       - Bidder's signature proving they authorized this bid.
   * @param bidder    - Public key of the new bidder.
   * @param bidAmount - Bid in satoshis; must exceed the current highest bid.
   */
  public bid(sig: Sig, bidder: PubKey, bidAmount: bigint) {
    // Verify the bidder authorized this bid (prevents griefing by bidding on others' behalf)
    assert(checkSig(sig, bidder));

    // Reject bids that do not exceed the current highest
    assert(bidAmount > this.highestBid);

    // The bid must be paid into the pot (N-027): the continuation carries the
    // prior pot plus the new bid. This example never refunds an outbid bidder,
    // so the pot is the deposit plus every bid, and close() hands all of it to
    // the auctioneer. `>=` lets a bidder add more; the compiler's own
    // `>= input` floor alone would let a bid pay nothing.
    assert(continuationAmount() >= extractAmount(this.txPreimage) + bidAmount);

    // Persist new leader into on-chain state
    this.highestBidder = bidder;
    this.highestBid = bidAmount;
  }

  /**
   * Close the auction after the deadline has passed.
   *
   * Non-mutating: the compiler auto-injects `checkPreimage` but does NOT
   * append a state-continuation output, so the UTXO is fully spent (no
   * successor). Only the auctioneer may call this.
   *
   * @param sig - Signature from the auctioneer proving ownership.
   */
  public close(sig: Sig) {
    // Verify the caller is the auctioneer
    assert(checkSig(sig, this.auctioneer));

    // Enforce that the deadline has passed: nLockTime must be >= deadline
    assert(extractLocktime(this.txPreimage) >= this.deadline);

    // ...and that consensus actually enforces that nLockTime. A transaction
    // whose inputs are all final (nSequence 0xffffffff) is mineable at any
    // height with nLockTime ignored, so without this the assert above is
    // script-only theatre and the auctioneer can close immediately.
    assert(extractSequence(this.txPreimage) !== 0xffffffffn);
  }
}

import {
  SmartContract,
  assert,
  bbFieldAdd,
  bbFieldSub,
  bbFieldMul,
  bbFieldInv,
  bbExt4Mul0,
  bbExt4Mul1,
  bbExt4Mul2,
  bbExt4Mul3,
  bbExt4Inv0,
  bbExt4Inv1,
  bbExt4Inv2,
  bbExt4Inv3,
} from 'runar-lang';

class BabyBearExt4Demo extends SmartContract {
  constructor() {
    super();
  }

  /** Ext4 multiplication: verify all 4 components */
  public checkMul(
    a0: bigint, a1: bigint, a2: bigint, a3: bigint,
    b0: bigint, b1: bigint, b2: bigint, b3: bigint,
    e0: bigint, e1: bigint, e2: bigint, e3: bigint,
  ) {
    assert(bbExt4Mul0(a0, a1, a2, a3, b0, b1, b2, b3) === e0);
    assert(bbExt4Mul1(a0, a1, a2, a3, b0, b1, b2, b3) === e1);
    assert(bbExt4Mul2(a0, a1, a2, a3, b0, b1, b2, b3) === e2);
    assert(bbExt4Mul3(a0, a1, a2, a3, b0, b1, b2, b3) === e3);
  }

  /** Ext4 inverse: verify all 4 components */
  public checkInv(
    a0: bigint, a1: bigint, a2: bigint, a3: bigint,
    e0: bigint, e1: bigint, e2: bigint, e3: bigint,
  ) {
    assert(bbExt4Inv0(a0, a1, a2, a3) === e0);
    assert(bbExt4Inv1(a0, a1, a2, a3) === e1);
    assert(bbExt4Inv2(a0, a1, a2, a3) === e2);
    assert(bbExt4Inv3(a0, a1, a2, a3) === e3);
  }

  /** FRI colinearity check: the core FRI folding relation */
  public checkFriFold(
    x: bigint,
    fx0: bigint, fx1: bigint, fx2: bigint, fx3: bigint,
    fnx0: bigint, fnx1: bigint, fnx2: bigint, fnx3: bigint,
    a0: bigint, a1: bigint, a2: bigint, a3: bigint,
    eg0: bigint, eg1: bigint, eg2: bigint, eg3: bigint,
  ) {
    const s0 = bbFieldAdd(fx0, fnx0);
    const s1 = bbFieldAdd(fx1, fnx1);
    const s2 = bbFieldAdd(fx2, fnx2);
    const s3 = bbFieldAdd(fx3, fnx3);
    const inv2 = bbFieldInv(2n);
    const hs0 = bbFieldMul(s0, inv2);
    const hs1 = bbFieldMul(s1, inv2);
    const hs2 = bbFieldMul(s2, inv2);
    const hs3 = bbFieldMul(s3, inv2);
    const d0 = bbFieldSub(fx0, fnx0);
    const d1 = bbFieldSub(fx1, fnx1);
    const d2 = bbFieldSub(fx2, fnx2);
    const d3 = bbFieldSub(fx3, fnx3);
    const ad0 = bbExt4Mul0(a0, a1, a2, a3, d0, d1, d2, d3);
    const ad1 = bbExt4Mul1(a0, a1, a2, a3, d0, d1, d2, d3);
    const ad2 = bbExt4Mul2(a0, a1, a2, a3, d0, d1, d2, d3);
    const ad3 = bbExt4Mul3(a0, a1, a2, a3, d0, d1, d2, d3);
    const inv2x = bbFieldInv(bbFieldMul(2n, x));
    const at0 = bbFieldMul(ad0, inv2x);
    const at1 = bbFieldMul(ad1, inv2x);
    const at2 = bbFieldMul(ad2, inv2x);
    const at3 = bbFieldMul(ad3, inv2x);
    const g0 = bbFieldAdd(hs0, at0);
    const g1 = bbFieldAdd(hs1, at1);
    const g2 = bbFieldAdd(hs2, at2);
    const g3 = bbFieldAdd(hs3, at3);
    assert(g0 === eg0);
    assert(g1 === eg1);
    assert(g2 === eg2);
    assert(g3 === eg3);
  }
}

import {
  SmartContract, assert,
  bbFieldAdd, bbFieldSub, bbFieldMul, bbFieldInv,
} from 'runar-lang';

/**
 * BabyBearDemo — Demonstrates Baby Bear prime field arithmetic.
 *
 * Baby Bear is the prime field used by SP1 STARK proofs (FRI verification).
 * Field prime: p = 2^31 - 2^27 + 1 = 2013265921
 *
 * Four operations:
 * - bbFieldAdd(a, b) — (a + b) mod p
 * - bbFieldSub(a, b) — (a - b + p) mod p
 * - bbFieldMul(a, b) — (a * b) mod p
 * - bbFieldInv(a) — a^(p-2) mod p (multiplicative inverse via Fermat)
 */
class BabyBearDemo extends SmartContract {
  constructor() {
    super();
  }

  /** Verify field addition. */
  public checkAdd(a: bigint, b: bigint, expected: bigint) {
    assert(bbFieldAdd(a, b) === expected);
  }

  /** Verify field subtraction. */
  public checkSub(a: bigint, b: bigint, expected: bigint) {
    assert(bbFieldSub(a, b) === expected);
  }

  /** Verify field multiplication. */
  public checkMul(a: bigint, b: bigint, expected: bigint) {
    assert(bbFieldMul(a, b) === expected);
  }

  /** Verify field inversion: a * inv(a) === 1. */
  public checkInv(a: bigint) {
    const inv = bbFieldInv(a);
    assert(bbFieldMul(a, inv) === 1n);
  }

  /** Verify subtraction is the inverse of addition: (a + b) - b === a. */
  public checkAddSubRoundtrip(a: bigint, b: bigint) {
    const sum = bbFieldAdd(a, b);
    const result = bbFieldSub(sum, b);
    assert(result === a);
  }

  /** Verify distributive law: a * (b + c) === a*b + a*c. */
  public checkDistributive(a: bigint, b: bigint, c: bigint) {
    const lhs = bbFieldMul(a, bbFieldAdd(b, c));
    const rhs = bbFieldAdd(bbFieldMul(a, b), bbFieldMul(a, c));
    assert(lhs === rhs);
  }
}

import { SmartContract, assert } from 'runar-lang';

class BitwiseOps extends SmartContract {
  readonly a: bigint;
  readonly b: bigint;

  constructor(a: bigint, b: bigint) {
    super(a, b);
    this.a = a;
    this.b = b;
  }

  public testShift(): void {
    const left = this.a << 2n;
    const right = this.a >> 1n;
    assert(left >= 0n || left < 0n);
    assert(right >= 0n || right < 0n);
    assert(true);
  }

  public testBitwise(): void {
    const andResult = this.a & this.b;
    const orResult = this.a | this.b;
    const xorResult = this.a ^ this.b;
    const notResult = ~this.a;
    assert(andResult >= 0n || andResult < 0n);
    assert(orResult >= 0n || orResult < 0n);
    assert(xorResult >= 0n || xorResult < 0n);
    assert(notResult >= 0n || notResult < 0n);
    assert(true);
  }
}

import { SmartContract, assert } from 'runar-lang';

class BooleanLogic extends SmartContract {
  readonly threshold: bigint;

  constructor(threshold: bigint) {
    super(threshold);
    this.threshold = threshold;
  }

  public verify(a: bigint, b: bigint, flag: boolean): void {
    const aAboveThreshold: boolean = a > this.threshold;
    const bAboveThreshold: boolean = b > this.threshold;
    const bothAbove: boolean = aAboveThreshold && bAboveThreshold;
    const eitherAbove: boolean = aAboveThreshold || bAboveThreshold;
    const notFlag: boolean = !flag;
    assert(bothAbove || (eitherAbove && notFlag));
  }
}

import { SmartContract, assert } from 'runar-lang';

class BoundedLoop extends SmartContract {
  readonly expectedSum: bigint;

  constructor(expectedSum: bigint) {
    super(expectedSum);
    this.expectedSum = expectedSum;
  }

  public verify(start: bigint): void {
    let sum: bigint = 0n;
    for (let i: bigint = 0n; i < 5; i++) {
      sum = sum + start + i;
    }
    assert(sum === this.expectedSum);
  }
}

import { StatefulSmartContract } from 'runar-lang';

/**
 * BranchMergedLocals -- regression fixture for the branch-merged-local
 * miscompilation reported privately on 2026-08-03.
 *
 * Two locals are initialised from state fields and the arms of an `if`
 * reassign DIFFERENT ones, then both feed the continuation. An `if` carries a
 * single value, so ANF lowering could only rewire post-branch references for
 * ONE merged local; with two, every later reference still named the dead
 * pre-branch binding, and stack lowering registered one stack-map slot for two
 * physical results and resolved every later operand one slot off. The script
 * compiled cleanly, passed the ANF-interpreter tests, and was rejected by the
 * real Script interpreter -- a permanently unspendable contract from idiomatic
 * source.
 *
 * Both arms now end with the same canonical result block, so the merged values
 * survive whichever branch runs. See
 * packages/runar-testing/src/__tests__/branch-merged-locals-vm.test.ts for the
 * real-Script-VM proof.
 */
class BranchMergedLocals extends StatefulSmartContract {
  a: bigint;
  b: bigint;

  constructor(a: bigint, b: bigint) {
    super(a, b);
    this.a = a;
    this.b = b;
  }

  public bid(amount: bigint, toFirst: bigint) {
    let na = this.a;
    let nb = this.b;
    if (toFirst > 0n) {
      na = amount;
    } else {
      nb = amount;
    }
    this.addOutput(1000n, na, nb);
  }
}

import { StatefulSmartContract, ByteString, len, toByteString } from 'runar-lang';

/**
 * BranchedReadonlyLen exercises a state-mutating if/else branched on a
 * read-only intrinsic value (`len`). The hand-off section 3
 * affine-checker concern: branching on a `bigint`-returning intrinsic
 * with state mutations on both arms must pass the affine type checker.
 * If this contract compiles cleanly across all 7 tiers, the
 * AdvanceState fold-in (BSVM-side) is unblocked.
 */
class BranchedReadonlyLen extends StatefulSmartContract {
  count: bigint;
  tag: ByteString;

  constructor(count: bigint, tag: ByteString) {
    super(count, tag);
    this.count = count;
    this.tag = tag;
  }

  public spend(scratch: ByteString) {
    if (len(scratch) > 0n) {
      this.count = this.count + 1n;
      this.tag = scratch;
    } else {
      this.count = this.count - 1n;
      this.tag = toByteString('3030');
    }
    this.addOutput(1000n, this.count, this.tag);
  }
}

import { SmartContract, assert, Sig, PubKey, Addr, hash160, checkSig } from 'runar-lang';

/**
 * BSV20Token -- Pay-to-Public-Key-Hash lock for a BSV-20 fungible token.
 *
 * BSV-20 is a 1sat ordinals token standard where fungible tokens are represented
 * as inscriptions on P2PKH UTXOs. The contract logic is standard P2PKH -- the
 * token semantics (deploy, mint, transfer) are encoded in the inscription
 * envelope and interpreted by indexers, not by the script itself.
 *
 * ## BSV-20 Token Lifecycle
 *
 * 1. **Deploy** -- Inscribe a deploy JSON (`{"p":"bsv-20","op":"deploy","tick":"RUNAR","max":"21000000"}`)
 *    onto a UTXO to register a new ticker. First deployer wins.
 * 2. **Mint** -- Inscribe a mint JSON (`{"p":"bsv-20","op":"mint","tick":"RUNAR","amt":"1000"}`)
 *    to claim tokens up to the per-mint limit.
 * 3. **Transfer** -- Inscribe a transfer JSON (`{"p":"bsv-20","op":"transfer","tick":"RUNAR","amt":"50"}`)
 *    to move tokens between addresses.
 *
 * The SDK helpers `BSV20.deploy()`, `BSV20.mint()`, and `BSV20.transfer()`
 * build the correct inscription payloads for each operation.
 */
class BSV20Token extends SmartContract {
  readonly pubKeyHash: Addr;

  constructor(pubKeyHash: Addr) {
    super(pubKeyHash);
    this.pubKeyHash = pubKeyHash;
  }

  /** Unlock by proving ownership of the private key corresponding to pubKeyHash. */
  public unlock(sig: Sig, pubKey: PubKey) {
    assert(hash160(pubKey) === this.pubKeyHash);
    assert(checkSig(sig, pubKey));
  }
}

import { SmartContract, assert, Sig, PubKey, Addr, hash160, checkSig } from 'runar-lang';

/**
 * BSV21Token -- Pay-to-Public-Key-Hash lock for a BSV-21 fungible token.
 *
 * BSV-21 (v2) is an improvement over BSV-20 that uses ID-based tokens instead
 * of tick-based. The token ID is derived from the deploy transaction
 * (`<txid>_<vout>`), eliminating ticker squatting and enabling admin-controlled
 * distribution.
 *
 * ## BSV-21 Token Lifecycle
 *
 * 1. **Deploy+Mint** -- A single inscription deploys the token and mints the
 *    initial supply in one atomic operation. The token ID is the outpoint of the
 *    output containing this inscription.
 * 2. **Transfer** -- Inscribe a transfer JSON referencing the token ID and amount.
 *
 * The SDK helpers `BSV21.deployMint()` and `BSV21.transfer()` build the correct
 * inscription payloads for each operation.
 */
class BSV21Token extends SmartContract {
  readonly pubKeyHash: Addr;

  constructor(pubKeyHash: Addr) {
    super(pubKeyHash);
    this.pubKeyHash = pubKeyHash;
  }

  /** Unlock by proving ownership of the private key corresponding to pubKeyHash. */
  public unlock(sig: Sig, pubKey: PubKey) {
    assert(hash160(pubKey) === this.pubKeyHash);
    assert(checkSig(sig, pubKey));
  }
}

import { SmartContract, assert, sha256, ripemd160, split, int2str, reverseBytes } from 'runar-lang';
import type { ByteString, Sha256, Ripemd160 } from 'runar-lang';

/**
 * ByteBuiltins — executed coverage for five byte-level builtins that no
 * conformance fixture called.
 *
 * Measured before this file landed: of the 105 `export function`s in
 * `packages/runar-lang/src/builtins.ts`, `split`, `int2str`, `reverseBytes`
 * and the `Sha256Hash` spelling of `sha256` appeared in ZERO fixtures'
 * `expected-ir.json`, and the fuzzer could not generate any of them. Seven
 * compilers shipped codegen for all four with nothing on either side of it:
 * no cross-tier byte comparison, and no execution.
 *
 * That is the shape the `pow` bug hid in. `pow` DID have a callsite
 * (`math-demo.exponentiate`) and still returned `base^min(exp,32)` for three
 * review rounds, because the callsite was only ever compiled, never spent past
 * the bound. So a callsite is not the deliverable here; the deliverable is a
 * script that gets SPENT at each builtin's boundaries.
 *
 * Every parameter is an unlock argument rather than a baked constant, so one
 * compiled script covers the whole domain. The boundaries this shape exists to
 * reach are driven from `conformance/byte_builtins_execution_test.go`:
 *
 *   split        index 0, index == len, the empty string, and the
 *                out-of-range indices consensus must abort on
 *   int2str      zero, negative, zero width, and a width too small to hold
 *                the value (OP_NUM2BIN's own failure)
 *   reverseBytes empty, one byte, odd length, and 520 bytes — the maximum BSV
 *                element, which is the last of the 520 unrolled iterations
 *   sha256       spelled `Sha256Hash` in the `.runar.go` surface, the only
 *                surface whose parser resolves that alias
 *   ripemd160    the `.runar.go` surface's ONLY spelling for it is
 *                `runar.Ripemd160`, which the TypeScript and Ruby parsers
 *                lowered to an identity binding — the opcode vanished, and the
 *                baked digest became the spending key. That is why this builtin
 *                had zero fixtures: nothing could call it from the Go surface
 *                without wedging cross-tier parity. The parser bug is fixed;
 *                `checkRipemd` is the end-to-end proof, and it is the reason
 *                this contract bakes a SECOND digest.
 *
 * NOTE on `split`: it is single-valued and binds the RIGHT half, lowering to
 * `OP_SPLIT OP_NIP`. Rúnar has no tuple type and no parser accepts array
 * destructuring, so a pair would be unnameable; `left(data, idx)` is the other
 * side of the same cut. `runar-lang` used to declare
 * `split(): [ByteString, ByteString]`, which disagreed with every typechecker
 * and with this file.
 */
class ByteBuiltins extends SmartContract {
  readonly expectedDigest: Sha256;
  readonly expectedRipemd: Ripemd160;

  constructor(expectedDigest: Sha256, expectedRipemd: Ripemd160) {
    super(expectedDigest, expectedRipemd);
    this.expectedDigest = expectedDigest;
    this.expectedRipemd = expectedRipemd;
  }

  /** OP_SPLIT. Binds the right half of `data` at `idx`. */
  public checkSplit(data: ByteString, idx: bigint, expectedTail: ByteString): void {
    const tail: ByteString = split(data, idx);
    assert(tail == expectedTail);
  }

  /** OP_NUM2BIN. Fixed-width little-endian sign-magnitude encoding. */
  public checkInt2Str(value: bigint, width: bigint, expected: ByteString): void {
    const s: ByteString = int2str(value, width);
    assert(s == expected);
  }

  /** 520 unrolled OP_SPLIT / OP_CAT iterations — one per possible byte. */
  public checkReverse(data: ByteString, expected: ByteString): void {
    const r: ByteString = reverseBytes(data);
    assert(r == expected);
  }

  /** OP_SHA256, against the digest baked into the locking script. */
  public checkSha256(preimage: ByteString): void {
    const h: Sha256 = sha256(preimage);
    assert(h == this.expectedDigest);
  }

  /** OP_RIPEMD160, against the digest baked into the locking script. */
  public checkRipemd(preimage: ByteString): void {
    const h: Ripemd160 = ripemd160(preimage);
    assert(h == this.expectedRipemd);
  }
}

import { StatefulSmartContract, assert, checkSig } from 'runar-lang';
import type { PubKey, Sig, ByteString } from 'runar-lang';

/**
 * AttributedToken -- a token whose immutable ATTRIBUTES are baked into the
 * code part of its locking script, so a later covenant can verify them by
 * inspecting the token's parent transaction in Bitcoin Script.
 *
 * This is the token half of the "Verified Companion Inputs" example pair
 * (see CompanionVerifier.runar.ts for the verifier half): cross-contract
 * composition where one covenant input verifies attributes of ANOTHER input
 * in the same spending transaction -- no oracle, no indexer, no coordinator.
 *
 * Design rules that make the attributes verifiable:
 *
 *  - **Attributes travel in the code part.** `attestor`, `category`, and
 *    `batchId` are readonly and baked at deploy; every child produced by a
 *    split inherits them byte-for-byte because the children reuse the same
 *    code part.
 *  - **An attribute only exists on-chain if the contract references it.**
 *    Unreferenced readonly props are eliminated by the compiler. `revoke`
 *    references `attestor` (checkSig) and `category` (enum floor assert)
 *    precisely so both become constructorSlots a downstream verifier can
 *    extract. This is the load-bearing rule of the whole pattern.
 *  - **Amount is divisible; attribution is not.** `split` conserves `amount`
 *    across children; the attribute slots are indivisible provenance.
 *
 * ATTRIBUTE SLOT ENCODING (fixed-layout template requirement):
 *  - `attestor` is a 33-byte pubkey push -- a fixed-width 33-byte slot.
 *  - `category` is constrained to 1..16 so it always bakes as a SINGLE OP_N
 *    opcode byte (0x51..0x60). 0 would bake as OP_0 (indistinguishable from
 *    an unbaked placeholder); 17+ bakes as a 2-byte push, shifting every
 *    offset after the slot. Fixed-width slots keep the verifier's offsets
 *    compile-time constants.
 *
 * The verifier derives those offsets mechanically from the artifact's
 * verification descriptors (`resolveSlotLayout` / `computeTemplateHash` in
 * runar-sdk) -- see the test file for the derivation.
 *
 * State model (UTXO): mutable state (owner, amount, status) rides in an
 * OP_RETURN tail; spending with the same code part = transfer/split.
 * Status: 1 = Active, 3 = Retired (consumed), 4 = Revoked (attestor recall).
 */
class AttributedToken extends StatefulSmartContract {
  /** Current holder. Mutable -- updated on transfer/split. */
  owner: PubKey;
  /** Divisible quantity. Mutable -- divided on split, conserved across children. */
  amount: bigint;
  /** Lifecycle status: 1 = Active, 3 = Retired, 4 = Revoked. Mutable. */
  status: bigint;

  /** ATTRIBUTE SLOT #1: who attested/minted this token. Readonly, baked into
   *  the code part -- the field a downstream CompanionVerifier extracts and
   *  checks against its allowlist. */
  readonly attestor: PubKey;
  /** ATTRIBUTE SLOT #2: category enum (1..16 ONLY -- see encoding note above).
   *  Readonly, baked as a single OP_N opcode byte. */
  readonly category: bigint;
  /** Batch identity -- hash of genesis metadata. Readonly, inherited by all children. */
  readonly batchId: ByteString;

  constructor(
    owner: PubKey,
    amount: bigint,
    status: bigint,
    attestor: PubKey,
    category: bigint,
    batchId: ByteString,
  ) {
    super(owner, amount, status, attestor, category, batchId);
    this.owner = owner;
    this.amount = amount;
    this.status = status;
    this.attestor = attestor;
    this.category = category;
    this.batchId = batchId;
  }

  /** Full transfer: 1 UTXO -> 1 UTXO. Whole amount to a new owner. */
  public transfer(sig: Sig, to: PubKey, outputSatoshis: bigint) {
    assert(checkSig(sig, this.owner));
    assert(this.status === 1n);
    assert(outputSatoshis >= 1n);

    this.addOutput(outputSatoshis, to, this.amount, this.status);
  }

  /**
   * Split: 1 UTXO -> 2 UTXOs. Recipient gets `splitAmount`, owner keeps the
   * remainder. Amount is conserved; attestor/category/batchId are inherited
   * automatically because both children reuse this same code part.
   */
  public split(sig: Sig, to: PubKey, splitAmount: bigint, outputSatoshis: bigint) {
    assert(checkSig(sig, this.owner));
    assert(this.status === 1n);
    assert(outputSatoshis >= 1n);
    assert(splitAmount > 0n);
    assert(splitAmount < this.amount);

    this.addOutput(outputSatoshis, to, splitAmount, this.status);
    this.addOutput(outputSatoshis, this.owner, this.amount - splitAmount, this.status);
  }

  /** Retire: mark the token consumed. Active -> Retired. Amount and owner
   *  preserved as the permanent record. */
  public retire(sig: Sig, outputSatoshis: bigint) {
    assert(checkSig(sig, this.owner));
    assert(this.status === 1n);
    assert(outputSatoshis >= 1n);

    this.addOutput(outputSatoshis, this.owner, this.amount, 3n);
  }

  /**
   * Revoke: attestor-only error correction. Active -> Revoked (status 4).
   *
   * Beyond its business meaning, this method is what forces BOTH attribute
   * slots on-chain: `checkSig(sig, this.attestor)` bakes the attestor pubkey
   * as a constructorSlot, and the `category` floor assert bakes the category
   * opcode. Attributes you can verify in Script exist only because the
   * contract itself commits to them.
   */
  public revoke(sig: Sig, outputSatoshis: bigint) {
    assert(checkSig(sig, this.attestor));
    // On-chain anchor for `category` + enum floor (0 would bake as an OP_0
    // placeholder-lookalike -- see the encoding note on the property).
    assert(this.category >= 1n);
    assert(this.status === 1n);
    assert(outputSatoshis >= 1n);

    this.addOutput(outputSatoshis, this.owner, this.amount, 4n);
  }
}

import {
  StatefulSmartContract, assert, checkSig, hash256, substr, len, cat, bin2num,
  extractHashPrevouts, extractOutpoint, extractOutputHash,
} from 'runar-lang';
import type { PubKey, Sig, ByteString, Sha256 } from 'runar-lang';

/**
 * CompanionVerifier -- the "Verified Companion Inputs" pattern: a Bitcoin
 * Script covenant that verifies ATTRIBUTES of a companion input by parsing
 * that input's parent transaction, bound to the spending transaction via the
 * BIP-143 preimage. No oracle, no indexer, no coordinator.
 *
 * This demonstrates cross-contract composition one step beyond
 * `examples/ts/cross-covenant/` (which verifies externally supplied output
 * data against a known script hash): here the external data is a FULL parent
 * transaction, cryptographically bound to a real input of THIS spend, and
 * the companion's contract identity is proven by template hash rather than
 * exact script hash -- so the check survives per-instance attribute values.
 *
 * The normative steps (each numbered in the method body):
 *  1. PREVOUTS BINDING -- `allPrevouts` (unlock data) is bound to THIS tx:
 *     hash256(allPrevouts) === hashPrevouts(preimage).
 *  2. POSITIONAL CONVENTION -- this covenant is input 0; the companion is
 *     input 1; the companion UTXO is output 0 of its parent tx.
 *  3. PARENT BINDING -- the supplied parent tx is bound by hash:
 *     hash256(parentTx) === txid in the companion's outpoint. Outpoint txids
 *     are in INTERNAL byte order -- the same order hash256 produces -- so the
 *     comparison is like-for-like, NO byte reversal (the classic footgun).
 *  4. STRUCTURAL WALK -- deterministic parse of the parent's bytes (bounded
 *     multi-input skip, 1..3 inputs) to output 0's locking script.
 *  5. TEMPLATE IDENTITY -- hash256 of that script with the attribute slots
 *     EXCISED must equal the known template hash. This proves the companion
 *     IS an instance of the expected contract and defeats attribute-planting
 *     counterfeits.
 *  6. ATTRIBUTE EXTRACTION + PREDICATE -- substr the fixed-width slots; apply
 *     the predicate (here: allowlist membership + category equality + state
 *     threshold; any predicate over the extracted bytes works).
 *  7. OUTPUT BINDING -- hash256(expectedOutputs) === hashOutputs(preimage), so
 *     ALL covenants in the tx agree on one output set (terminal form).
 *
 * SECURITY NOTE on excised slots: the template hash is a SHAPE commitment.
 * Every excised slot is attacker-controlled bytes until the covenant
 * value-checks it -- which is why step 6 checks BOTH slots (allowlist for
 * the attestor, exact OP_N compare for the category). Never excise a slot
 * you do not also value-check.
 *
 * SIGN-BYTE DISCIPLINE: every bin2num on parsed bytes is padded with a
 * trailing zero byte (`cat(bytes, PAD00)`) so values whose top bit is set can
 * never read negative. This is the bug class the pattern must codify.
 *
 * The baked layout constants (attestorOffset / categoryOffset / codePostLen /
 * expectedTemplateHash) come from the companion artifact's verification
 * descriptors: `resolveSlotLayout` + `computeTemplateHash` in runar-sdk.
 * See the test file for the derivation.
 */
class CompanionVerifier extends StatefulSmartContract {
  /** Operator of this verifier. Mutable state. */
  owner: PubKey;
  /** Count of companions verified. Mutable state. */
  companionsVerified: bigint;

  /** Byte offset of attribute slot #1 (33-byte attestor pubkey) inside the
   *  companion's locking script (from its constructorSlots). */
  readonly attestorOffset: bigint;
  /** Byte offset of attribute slot #2 (single OP_N category opcode; the enum
   *  is constrained to 1..16 so the slot is always exactly 1 byte). Must be
   *  > attestorOffset + 33. */
  readonly categoryOffset: bigint;
  /** Length of the companion code part AFTER the category slot ends
   *  (codeLen - categoryOffset - 1). */
  readonly codePostLen: bigint;
  /** hash256 of the companion code part with BOTH attribute slots excised
   *  (33-byte attestor + 1-byte category) -- the template identity. */
  readonly expectedTemplateHash: Sha256;
  /** Attribute predicate data: approved attestors (allowlist of 2). */
  readonly allowedAttestor1: PubKey;
  readonly allowedAttestor2: PubKey;
  /** Attribute predicate data: minimum companion amount accepted. */
  readonly minAmount: bigint;
  /** Attribute predicate data: required category enum value (1..16). The
   *  companion's baked opcode must equal OP_N for this N (byte = 0x50 + N). */
  readonly requiredCategory: bigint;

  /** Zero pad for sign-safe bin2num on parsed little-endian fields. */
  readonly pad00: ByteString = "00" as ByteString;

  constructor(
    owner: PubKey,
    companionsVerified: bigint,
    attestorOffset: bigint,
    categoryOffset: bigint,
    codePostLen: bigint,
    expectedTemplateHash: Sha256,
    allowedAttestor1: PubKey,
    allowedAttestor2: PubKey,
    minAmount: bigint,
    requiredCategory: bigint,
  ) {
    super(owner, companionsVerified, attestorOffset, categoryOffset, codePostLen, expectedTemplateHash, allowedAttestor1, allowedAttestor2, minAmount, requiredCategory);
    this.owner = owner;
    this.companionsVerified = companionsVerified;
    this.attestorOffset = attestorOffset;
    this.categoryOffset = categoryOffset;
    this.codePostLen = codePostLen;
    this.expectedTemplateHash = expectedTemplateHash;
    this.allowedAttestor1 = allowedAttestor1;
    this.allowedAttestor2 = allowedAttestor2;
    this.minAmount = minAmount;
    this.requiredCategory = requiredCategory;
  }

  /**
   * Verify the companion input (input 1) against this verifier's attribute
   * predicate, by parsing the companion's parent transaction in Script.
   *
   * TERMINAL method: this UTXO is fully spent; no continuation. The spending
   * tx's outputs are bound via extractOutputHash, and the companion input's
   * own covenant (e.g. AttributedToken.retire) independently enforces ITS
   * continuation -- so both covenant inputs agree on the same output set.
   *
   * @param sig               - owner's signature
   * @param allPrevouts       - concatenated 36-byte outpoints of ALL inputs of THIS tx
   * @param companionParentTx - full serialized parent transaction of the companion input
   * @param expectedOutputs   - serialized outputs of THIS tx (value8|varint|script per output)
   */
  public verifyCompanion(sig: Sig, allPrevouts: ByteString, companionParentTx: ByteString, expectedOutputs: ByteString) {
    assert(checkSig(sig, this.owner));

    // -- 1. Bind allPrevouts to the real spending tx. --
    assert(hash256(allPrevouts) === extractHashPrevouts(this.txPreimage));
    assert(len(allPrevouts) >= 72n); // at least: this input + the companion input

    // -- 2. Positional convention: I am input 0; the companion is input 1. --
    const myOutpoint = extractOutpoint(this.txPreimage);
    assert(substr(allPrevouts, 0n, 36n) === myOutpoint);
    const companionOutpoint = substr(allPrevouts, 36n, 36n);
    const companionTxid = substr(companionOutpoint, 0n, 32n);
    // vout must be 0 (sign-safe read of 4-byte LE)
    const companionVout = bin2num(cat(substr(companionOutpoint, 32n, 4n), this.pad00));
    assert(companionVout === 0n);

    // -- 3. Bind the supplied parent tx by hash. Internal byte order both sides; no reversal. --
    assert(hash256(companionParentTx) === companionTxid);

    // -- 4. Walk to output 0's locking script. --
    // version(4) | inCount(varint) | inputs... | outCount(varint) | outputs... | locktime(4)
    // Bounded multi-input walk (1..3 inputs -- the general profile). inCount is
    // a 1-byte varint by construction: >3 rejects, and a 0xfd/0xfe/0xff marker
    // byte reads as 253/254/255 which also rejects.
    const inCount = bin2num(cat(substr(companionParentTx, 4n, 1n), this.pad00));
    assert(inCount >= 1n);
    assert(inCount <= 3n);
    // each input: outpoint(36) + scriptLen varint (1-byte only, sign-safe;
    // P2PKH unlock ~107B) + script + sequence(4)
    let off = 5n;
    for (let i = 0n; i < 3n; i++) {
      if (i < inCount) {
        const sl = bin2num(cat(substr(companionParentTx, off + 36n, 1n), this.pad00));
        assert(sl < 253n);
        off = off + 36n + 1n + sl + 4n;
      }
    }
    // outputs section starts at off
    const outCountPrefix = bin2num(cat(substr(companionParentTx, off, 1n), this.pad00));
    assert(outCountPrefix !== 254n);
    assert(outCountPrefix !== 255n);
    let outHdr = 1n;
    let outCount = outCountPrefix;
    if (outCountPrefix === 253n) {
      outCount = bin2num(cat(substr(companionParentTx, off + 1n, 2n), this.pad00));
      outHdr = 3n;
    }
    assert(outCount >= 1n);
    // output 0 = value(8) + scriptLen(varint) + script. Companion scripts are
    // >252B -> the varint MUST be 0xfd + LE16 (also rejects short scripts like P2PKH).
    const marker = bin2num(cat(substr(companionParentTx, off + outHdr + 8n, 1n), this.pad00));
    assert(marker === 253n);
    const scriptLen = bin2num(cat(substr(companionParentTx, off + outHdr + 9n, 2n), this.pad00));
    const scriptStart = off + outHdr + 11n;
    assert(len(companionParentTx) >= scriptStart + scriptLen);
    const companionScript = substr(companionParentTx, scriptStart, scriptLen);

    // -- 5. Template identity: the companion IS an instance of the expected
    //       contract. BOTH attribute slots are excised (33-byte attestor +
    //       1-byte category opcode), leaving a fixed-layout template.
    const codePre = substr(companionScript, 0n, this.attestorOffset);
    const codeMid = substr(companionScript, this.attestorOffset + 33n, this.categoryOffset - this.attestorOffset - 33n);
    const codePost = substr(companionScript, this.categoryOffset + 1n, this.codePostLen);
    assert(hash256(cat(cat(codePre, codeMid), codePost)) === this.expectedTemplateHash);

    // -- 6. Attribute extraction + predicate. --
    // 6a. Attestor allowlist membership (the worked predicate).
    const attestor = substr(companionScript, this.attestorOffset, 33n);
    assert(attestor === this.allowedAttestor1 || attestor === this.allowedAttestor2);

    // 6b. Category enum: the baked slot is the single opcode OP_N (byte
    //     0x50 + N). Read the raw opcode byte sign-safely and require it to
    //     encode exactly requiredCategory (1..16). NOTE: this slot is excised
    //     from the template, so WITHOUT this check an attacker could plant
    //     any byte here -- the sign-safe read also defeats bytes >= 0x80.
    const catOp = bin2num(cat(substr(companionScript, this.categoryOffset, 1n), this.pad00));
    assert(catOp === this.requiredCategory + 80n);

    // 6c. Predicates over the companion's STATE region (fixed 8-byte LE
    //     fields at the script tail: [.. owner(33) | amount(8) | status(8)]).
    //     Sign-safe reads: an 8-byte LE value with its top bit set (e.g.
    //     2^63) would read NEGATIVE unpadded -- the pad00 cat prevents it.
    const companionAmount = bin2num(cat(substr(companionScript, scriptLen - 16n, 8n), this.pad00));
    const companionStatus = bin2num(cat(substr(companionScript, scriptLen - 8n, 8n), this.pad00));
    assert(companionStatus === 1n); // must be Active (not Retired/Revoked)
    assert(companionAmount >= this.minAmount);

    // -- 7. Terminal output binding: the spending tx's outputs are exactly the supplied set. --
    assert(hash256(expectedOutputs) === extractOutputHash(this.txPreimage));
  }
}

import { SmartContract, assert, checkSig, hash160 } from 'runar-lang';
import type { Addr, ByteString, PubKey, Sig } from 'runar-lang';

/**
 * Directives — the two comment directives the compiler reads, in one contract.
 *
 * Both are real features with real on-chain consequences, and before R-209
 * neither had a single example anywhere in the repo: no `examples/`, no
 * conformance fixture, no mention in `docs/`. They were discoverable only by
 * reading the compiler's own tests.
 *
 * BOTH ARE `.runar.ts` ONLY. The other eight surface parsers reject a source
 * carrying either directive rather than silently ignoring it, because ignoring
 * one would change signing or DCE semantics without saying so.
 *
 * ---------------------------------------------------------------------------
 * `@embedAlways` — keep a readonly field the body never reads
 * ---------------------------------------------------------------------------
 * A readonly property that no method references is eliminated: its `load_prop`
 * is dead, so no constructor slot is emitted and the value never reaches the
 * locking script. That is usually right, and wrong for deploy-time metadata an
 * author intends to recover from the script later. `@embedAlways` opts the
 * field out of that elimination; without it the compiler emits a warning
 * naming the directive.
 *
 * The effect is visible in the artifact's `constructorSlots` — the byte offsets
 * the deploy-time values are spliced into — and NOT in `abi.constructor.params`,
 * which lists the declared signature and keeps the parameter either way. With
 * the directive the slots are [deployTag, ownerPKH, ownerPKH]; without it,
 * [ownerPKH, ownerPKH], and the value never reaches the locking script even
 * though the constructor still takes it.
 *
 * ---------------------------------------------------------------------------
 * `@sighash` — declare what the covenant commits to
 * ---------------------------------------------------------------------------
 * A public method's auto-injected covenant (and the preimage the SDK builds for
 * it) commits to `ALL|FORKID` by default. `@sighash` declares a different
 * BIP-143 mode. `SINGLE|FORKID` commits to only the output at the same index as
 * the input being signed, which is what lets one party fix their own output and
 * leave the rest of the transaction open for someone else to complete.
 *
 * Exactly one base type (`ALL`, `NONE`, `SINGLE`) must appear; `FORKID` and
 * `ANYONECANPAY` are modifiers.
 */
export class Directives extends SmartContract {
  readonly ownerPKH: Addr;

  /** @embedAlways */
  readonly deployTag: ByteString;

  constructor(ownerPKH: Addr, deployTag: ByteString) {
    super(ownerPKH, deployTag);
    this.ownerPKH = ownerPKH;
    this.deployTag = deployTag;
  }

  /** Default mode: no directive, so the covenant commits to ALL|FORKID. */
  public spendAll(sig: Sig, pubKey: PubKey) {
    assert(hash160(pubKey) === this.ownerPKH);
    assert(checkSig(sig, pubKey));
  }

  /** @sighash SINGLE|FORKID */
  public spendSingle(sig: Sig, pubKey: PubKey) {
    assert(hash160(pubKey) === this.ownerPKH);
    assert(checkSig(sig, pubKey));
  }
}

import { StatefulSmartContract } from 'runar-lang';

/**
 * CondWriteMultiField -- regression fixture for GitHub issue #99.
 *
 * A conditional write of TWO mutable state fields in an `if` WITHOUT an
 * `else`. The then-branch leaves two result values on the stack; the empty
 * else-branch must preserve two old values. The pre-fix stack lowering only
 * balanced a single item, leaving the IF/ELSE arms imbalanced by (N-1) and
 * the update branch unspendable. The compiler now reconciles the full depth
 * difference and asserts branch balance (invariant B).
 */
class CondWriteMultiField extends StatefulSmartContract {
  a: bigint;
  b: bigint;

  constructor(a: bigint, b: bigint) {
    super(a, b);
    this.a = a;
    this.b = b;
  }

  public bump(flag: bigint) {
    if (flag > 0n) {
      this.a = this.a + 1n;
      this.b = this.b + 2n;
    }
    this.addOutput(1000n, this.a, this.b);
  }
}

// ConditionalDataOutput — Audit regression: a stateful method that
// emits a data output on a conditional branch must keep the canonical
// single-output `computeStateOutput` state continuation on every path.
//
// # Background
//
// The pre-fix lowering registered ANY branch output as
// `addOutputRef`, regardless of whether the branch's outputs were
// state outputs (`addOutput` / `addRawOutput`) or data outputs
// (`addDataOutput`). That forced the parent method onto the
// multi-output continuation path, which OMITS the canonical
// single-output `computeStateOutput` call. The continuation hash for
// the stateful contract was therefore wrong on the branch where
// `addDataOutput` ran, and the spend would fail on chain.
//
// # Behavior
//
//   - `pay(flag, payload)` mutates `amount` unconditionally and emits
//     a data output (the receipt) only when `flag` is true. The
//     continuation must commit to the new state on both branches; the
//     data output bytes splice in BETWEEN the state output and the
//     change output when `flag` is true.
//
// # Cross-compiler scope
//
// All seven Rúnar compilers must produce identical Bitcoin Script for
// this contract. The conformance fixture lives at
// `conformance/tests/conditional-data-output-stateful/`.
import { StatefulSmartContract, ByteString, assert } from 'runar-lang';

export class ConditionalDataOutput extends StatefulSmartContract {
    amount: bigint;

    constructor(amount: bigint) {
        super(amount);
        this.amount = amount;
    }

    // The canonical bug: `addDataOutput` is wrapped in a branch.
    // The compiler must register the if's value as a DATA output
    // ref (not a state output ref) so that the parent method's
    // continuation hash keeps `computeStateOutput`.
    public pay(flag: boolean, payload: ByteString): void {
        this.amount = this.amount + 1n;
        if (flag) {
            this.addDataOutput(0n, payload);
        }
        assert(true);
    }
}

import {
  SmartContract, assert,
  ecAdd, ecNegate, ecMulGen, ecPointX, ecPointY, ecOnCurve,
} from 'runar-lang';
import type { Point } from 'runar-lang';

/**
 * OPRF-based fraud signal convergence proof.
 *
 * Two parties submit randomized tokens R_A = (T + o_A)·G and R_B = (T + o_B)·G
 * where T is the shared underlying token and o_A, o_B are ECDH-derived offsets.
 *
 * An authority who knows both offsets can prove the two submissions share the
 * same token T by providing Δo = o_A - o_B and verifying:
 *
 *   R_A - R_B = Δo · G
 *
 * The token T cancels out in the subtraction, proving convergence without
 * revealing T. Spending this UTXO serves as a formal on-chain subpoena trigger.
 */
class ConvergenceProof extends SmartContract {
  readonly rA: Point;
  readonly rB: Point;

  constructor(rA: Point, rB: Point) {
    super(rA, rB);
    this.rA = rA;
    this.rB = rB;
  }

  /**
   * Prove convergence via offset difference.
   *
   * @param deltaO - The offset difference o_A - o_B (mod n), provided by authority
   */
  public proveConvergence(deltaO: bigint) {
    // Verify both committed points are on the curve
    assert(ecOnCurve(this.rA));
    assert(ecOnCurve(this.rB));

    // R_A - R_B (point subtraction = addition with negated second operand)
    const diff = ecAdd(this.rA, ecNegate(this.rB));

    // Δo · G (scalar multiplication of generator)
    const expected = ecMulGen(deltaO);

    // Assert point equality via coordinate comparison
    assert(ecPointX(diff) === ecPointX(expected));
    assert(ecPointY(diff) === ecPointY(expected));
  }
}

import { SmartContract, assert } from 'runar-lang';

/**
 * CountdownLoop — the `step = -1` half of the loop shape (R-102).
 *
 * `loop-shapes` closed the non-zero-START half and said so explicitly: "The
 * descending half is still open: no fixture anywhere carries `step = -1`, and
 * three of the nine surfaces cannot spell a decrementing loop at all (N-130)."
 * That was accurate. Countdown lowering shipped in all seven tiers and
 * cross-tier parity had never once been measured on it.
 *
 * What the gap was hiding, found by closing it:
 *
 *   - The Move frontend's `while`-fold matched `i = i + …` only, so
 *     `i = i - 1` fell through to a synthetic stub whose trip count came out
 *     ZERO. Six tiers compiled the loop body — every assertion in it — clean
 *     out of the locking script, exit 0, no diagnostic.
 *   - The `.runar.zig` surface never set `descending` from its comparison in
 *     the Zig tier, so `while (i > 1) : (i -= 1)` unrolled zero times THERE
 *     while the other six lowered a real countdown from the same bytes.
 *   - `range(a, b, -1)`, `n.downto(m)` and `(a..b).rev()` did not parse at
 *     all: three of the nine surfaces could not spell a countdown, which is
 *     why no such fixture could exist.
 *
 * The loop descends:
 *
 *   loop 1 (i = 5n; i > 1n; i--):  5 + 4 + 3 + 2 = 14
 *
 * so `verify(seed)` asserts `seed + 14`.
 *
 * Two facts make that arithmetic worth asserting rather than just the trip
 * count: 14 is not 4 times anything, so a dropped body, a wrong start and an
 * ascending iterator each produce a different wrong sum; and the equivalent
 * ASCENDING loop of the same length (0, 1, 2, 3) sums to 6 — a number this
 * fixture must never accept.
 */
export class CountdownLoop extends SmartContract {
  readonly target: bigint;

  constructor(target: bigint) {
    super(target);
    this.target = target;
  }

  public verify(seed: bigint) {
    let acc: bigint = seed;
    for (let i = 5n; i > 1n; i--) {
      acc = acc + i;
    }
    assert(acc === this.target);
  }
}

import { SmartContract, assert, PubKey, Sig, Addr, ByteString, SigHashPreimage, checkSig, checkPreimage, extractOutputHash, hash256, num2bin, cat } from 'runar-lang';

/**
 * CovenantVault -- a stateless Bitcoin covenant contract.
 *
 * A covenant is a self-enforcing spending constraint: the locking script
 * dictates not just *who* can spend the funds, but *how* they may be spent.
 * This contract demonstrates the pattern by combining three verification
 * layers in its single public method:
 *
 *   1. Owner authorization  -- the owner's ECDSA signature must be valid
 *      (proves who is spending).
 *   2. Preimage verification -- `checkPreimage` (OP_PUSH_TX) proves the
 *      contract is inspecting the real spending transaction, enabling
 *      on-chain introspection of its fields.
 *   3. Covenant rule -- the contract constructs the expected P2PKH output
 *      on-chain (recipient address + `minAmount` satoshis) and verifies its
 *      hash against the transaction's `hashOutputs` field. This constrains
 *      both the destination and the amount at the consensus level.
 *
 * Script layout (simplified):
 *   Unlocking: <opPushTxSig> <sig> <txPreimage>
 *   Locking:   <pubKey> OP_CHECKSIG OP_VERIFY <checkPreimage>
 *              <buildP2PKH(recipient)> <num2bin(minAmount,8)> OP_CAT
 *              OP_HASH256 <extractOutputHash(preimage)> OP_EQUAL OP_VERIFY
 *
 * Use cases for this pattern include withdrawal limits, time-locked vaults,
 * rate-limited spending, and enforced change addresses.
 *
 * Contract model: Stateless (`SmartContract`). All constructor parameters
 * are `readonly` and baked into the locking script at deploy time.
 *
 * @param owner     - Owner's compressed public key (33 bytes). Only the
 *                    corresponding private key can produce a valid `sig`.
 * @param recipient - Recipient address hash (20 bytes, hash160 of pubkey).
 * @param minAmount - Exact satoshi value the spending transaction must
 *                    include in its output, enforced by the covenant rule.
 */
class CovenantVault extends SmartContract {
  /** Owner's compressed ECDSA public key (33 bytes). */
  readonly owner: PubKey;
  /** Recipient address (20-byte hash160 of the recipient's public key). */
  readonly recipient: Addr;
  /** Exact output amount in satoshis enforced by the covenant. */
  readonly minAmount: bigint;

  constructor(owner: PubKey, recipient: Addr, minAmount: bigint) {
    super(owner, recipient, minAmount);
    this.owner = owner;
    this.recipient = recipient;
    this.minAmount = minAmount;
  }

  /**
   * Spend funds held by this covenant.
   *
   * Enforces that the spending transaction creates exactly one P2PKH output
   * to the designated recipient with exactly `minAmount` satoshis. The
   * expected output is constructed on-chain and its hash is verified against
   * the sighash preimage's hashOutputs field, which commits to all outputs.
   * This means the transaction must have this single exact output — no
   * additional outputs or different amounts are permitted.
   *
   * @param sig        - ECDSA signature from the owner (~72 bytes DER).
   * @param txPreimage - Sighash preimage (variable length) used by
   *                     `checkPreimage` to verify the spending transaction.
   */
  public spend(sig: Sig, txPreimage: SigHashPreimage) {
    assert(checkSig(sig, this.owner));
    assert(checkPreimage(txPreimage));

    // Construct the expected P2PKH output on-chain:
    // <8-byte LE amount> <varint(25)> <OP_DUP OP_HASH160 OP_PUSH(20) recipient OP_EQUALVERIFY OP_CHECKSIG>
    const p2pkhScript = cat(cat('1976a914', this.recipient), '88ac');
    const expectedOutput = cat(num2bin(this.minAmount, 8n), p2pkhScript);

    // Verify the transaction's outputs match exactly
    assert(hash256(expectedOutput) === extractOutputHash(txPreimage));
  }
}

import {
  SmartContract, assert, hash256, substr, bin2num,
} from 'runar-lang';
import type { ByteString, Sha256 } from 'runar-lang';

/**
 * CrossCovenantRef — Demonstrates reading another covenant's output.
 *
 * This pattern allows one covenant to verify data from a DIFFERENT
 * transaction's output, enabling cross-covenant communication on BSV.
 *
 * How it works:
 * 1. The unlocking script passes the referenced output data as a parameter
 * 2. The covenant hashes it and compares against a known script hash
 * 3. If the hash matches, the data is authentic — extract fields from it
 *
 * This is NOT introspection of the current transaction (which OP_PUSH_TX
 * handles). It's verification of external data passed into the contract.
 *
 * Use cases:
 * - Bridge covenant reading state covenant's state root
 * - Side-chain anchor verifying main-chain commitments
 * - Oracle covenant referencing price feed covenant's data
 */
class CrossCovenantRef extends SmartContract {
  /** Hash of the expected source covenant's locking script. */
  readonly sourceScriptHash: Sha256;

  constructor(sourceScriptHash: Sha256) {
    super(sourceScriptHash);
    this.sourceScriptHash = sourceScriptHash;
  }

  /**
   * Verify a referenced output and extract a 32-byte state root from it.
   *
   * @param referencedOutput - The full serialized output from the source covenant
   *                           (8-byte LE amount + varint + script bytes)
   * @param expectedStateRoot - The state root we expect to find in the referenced output
   * @param stateRootOffset - Byte offset within the script where the state root starts
   */
  public verifyAndExtract(
    referencedOutput: ByteString,
    expectedStateRoot: ByteString,
    stateRootOffset: bigint,
  ) {
    // Step 1: Hash the referenced output and verify it matches the known script hash.
    // This proves the output data is authentic (came from the expected covenant).
    const outputHash = hash256(referencedOutput);
    assert(outputHash === this.sourceScriptHash);

    // Step 2: Extract the state root from the referenced output.
    // The caller provides the offset where the state root lives within the output.
    const stateRoot = substr(referencedOutput, stateRootOffset, 32n);

    // Step 3: Verify the extracted state root matches the expected value.
    assert(stateRoot === expectedStateRoot);
  }

  /**
   * Verify a referenced output and extract a numeric value from it.
   *
   * @param referencedOutput - The full serialized output from the source covenant
   * @param expectedValue - The numeric value we expect to find
   * @param valueOffset - Byte offset within the script
   * @param valueLen - Length in bytes of the numeric value
   */
  public verifyAndExtractNumeric(
    referencedOutput: ByteString,
    expectedValue: bigint,
    valueOffset: bigint,
    valueLen: bigint,
  ) {
    const outputHash = hash256(referencedOutput);
    assert(outputHash === this.sourceScriptHash);

    const valueBytes = substr(referencedOutput, valueOffset, valueLen);
    const value = bin2num(valueBytes);
    assert(value === expectedValue);
  }
}

import {
  SmartContract, assert,
  ecAdd, ecMul, ecMulGen, ecNegate, ecOnCurve, ecModReduce,
  ecEncodeCompressed, ecMakePoint, ecPointX, ecPointY,
  EC_N,
} from 'runar-lang';
import type { Point, ByteString } from 'runar-lang';

/**
 * ECDemo — A stateless contract demonstrating every built-in elliptic curve
 * primitive available in Runar.
 *
 * Runar provides 10 built-in functions for secp256k1 elliptic curve arithmetic.
 * These compile into Bitcoin Script opcodes that perform real EC math on-chain,
 * enabling advanced cryptographic protocols like Schnorr signatures, zero-knowledge
 * proofs, and key derivation — all enforced by the Bitcoin network.
 *
 * **Curve: secp256k1**
 * - Field prime p = 2^256 - 2^32 - 977
 * - Group order n = FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
 * - Generator point G is a fixed curve point; `ecMulGen(k)` computes k*G
 * - Points are 64 bytes: x[32] || y[32], big-endian unsigned, no prefix byte
 *
 * **How EC operations compile to Bitcoin Script:**
 * Each EC function expands into a sequence of stack operations during compilation.
 * For example, `ecMul` compiles to a 256-iteration double-and-add loop using
 * Jacobian coordinates — roughly 1,500 bytes of Script. `ecAdd` uses affine
 * addition with modular inverses — roughly 800 bytes. The compiler handles all
 * coordinate math automatically; the developer works with high-level point
 * operations.
 *
 * **The 10 EC primitives:**
 * 1. `ecPointX(p)` — Extract x-coordinate from a point
 * 2. `ecPointY(p)` — Extract y-coordinate from a point
 * 3. `ecMakePoint(x, y)` — Construct a point from coordinates
 * 4. `ecOnCurve(p)` — Check if a point lies on the curve
 * 5. `ecAdd(a, b)` — Add two curve points
 * 6. `ecMul(p, k)` — Scalar multiplication: k * P
 * 7. `ecMulGen(k)` — Generator multiplication: k * G (optimized)
 * 8. `ecNegate(p)` — Negate a point: (x, p - y)
 * 9. `ecModReduce(v, m)` — Modular reduction for group arithmetic
 * 10. `ecEncodeCompressed(p)` — Compress to 33-byte public key format
 *
 * This contract is stateless (`SmartContract`), so each method is an independent
 * spending condition. No signature checks are performed — the focus is purely on
 * demonstrating EC operations.
 */
class ECDemo extends SmartContract {
  /** A curve point stored as a contract property. Used as input to most methods. */
  readonly pt: Point;

  constructor(pt: Point) {
    super(pt);
    this.pt = pt;
  }

  // -------------------------------------------------------------------
  // Coordinate extraction and construction
  // -------------------------------------------------------------------

  /**
   * Extract the x-coordinate from the stored point and verify it matches
   * the expected value.
   *
   * `ecPointX` splits a 64-byte Point into its first 32 bytes (big-endian
   * unsigned x-coordinate) and converts to a script number.
   *
   * Use cases: comparing public key x-coordinates, Schnorr signature
   * verification (which only uses the x-coordinate).
   */
  public checkX(expectedX: bigint) {
    assert(ecPointX(this.pt) === expectedX);
  }

  /**
   * Extract the y-coordinate from the stored point and verify it matches
   * the expected value.
   *
   * `ecPointY` splits a 64-byte Point into its last 32 bytes (big-endian
   * unsigned y-coordinate) and converts to a script number.
   *
   * Use cases: full point comparison, parity checks for compressed encoding.
   */
  public checkY(expectedY: bigint) {
    assert(ecPointY(this.pt) === expectedY);
  }

  /**
   * Construct a point from x and y coordinates, then verify the result
   * matches the expected coordinates.
   *
   * `ecMakePoint(x, y)` encodes each coordinate as a 32-byte big-endian
   * unsigned integer and concatenates them into a 64-byte Point.
   *
   * Use cases: reconstructing points from stored coordinates, building
   * points from external data.
   */
  public checkMakePoint(x: bigint, y: bigint, expectedX: bigint, expectedY: bigint) {
    const p = ecMakePoint(x, y);
    assert(ecPointX(p) === expectedX);
    assert(ecPointY(p) === expectedY);
  }

  // -------------------------------------------------------------------
  // Curve membership
  // -------------------------------------------------------------------

  /**
   * Verify the stored point lies on the secp256k1 curve.
   *
   * `ecOnCurve(p)` checks the curve equation: y^2 === x^3 + 7 (mod p).
   * Returns true if the point satisfies the equation, false otherwise.
   *
   * Use cases: validating untrusted points from transaction inputs before
   * performing EC arithmetic (prevents invalid-curve attacks).
   */
  public checkOnCurve() {
    assert(ecOnCurve(this.pt));
  }

  // -------------------------------------------------------------------
  // Point arithmetic
  // -------------------------------------------------------------------

  /**
   * Add two curve points and verify the result.
   *
   * `ecAdd(a, b)` performs elliptic curve point addition using the affine
   * addition formula:
   *   lambda = (y2 - y1) / (x2 - x1) mod p
   *   x3 = lambda^2 - x1 - x2 mod p
   *   y3 = lambda(x1 - x3) - y1 mod p
   *
   * This compiles to ~800 bytes of Bitcoin Script including a modular
   * inverse computation.
   *
   * Use cases: combining public keys (key aggregation), Schnorr multi-sig,
   * Pedersen commitments (C = v*G + r*H).
   */
  public checkAdd(other: Point, expectedX: bigint, expectedY: bigint) {
    const result = ecAdd(this.pt, other);
    assert(ecPointX(result) === expectedX);
    assert(ecPointY(result) === expectedY);
  }

  /**
   * Multiply the stored point by a scalar and verify the result.
   *
   * `ecMul(p, k)` computes k * P using a 256-bit double-and-add algorithm
   * in Jacobian coordinates (to avoid per-step modular inverses). The final
   * result is converted back to affine coordinates.
   *
   * This is the most expensive EC operation: ~1,500 bytes of Bitcoin Script
   * with a 256-iteration loop.
   *
   * Use cases: public key derivation (P = k*G), Diffie-Hellman shared
   * secrets, BIP-32 child key derivation.
   */
  public checkMul(scalar: bigint, expectedX: bigint, expectedY: bigint) {
    const result = ecMul(this.pt, scalar);
    assert(ecPointX(result) === expectedX);
    assert(ecPointY(result) === expectedY);
  }

  /**
   * Multiply the generator point G by a scalar and verify the result.
   *
   * `ecMulGen(k)` is equivalent to `ecMul(EC_G, k)` but the generator
   * point is hardcoded into the compiled script, saving the overhead of
   * pushing 64 bytes of point data.
   *
   * Use cases: deriving a public key from a private key (the fundamental
   * operation in elliptic curve cryptography), generating nonce points
   * for Schnorr proofs (R = r*G).
   */
  public checkMulGen(scalar: bigint, expectedX: bigint, expectedY: bigint) {
    const result = ecMulGen(scalar);
    assert(ecPointX(result) === expectedX);
    assert(ecPointY(result) === expectedY);
  }

  // -------------------------------------------------------------------
  // Point negation
  // -------------------------------------------------------------------

  /**
   * Negate the stored point and verify the result's y-coordinate.
   *
   * `ecNegate(p)` returns the point (x, field_prime - y). This is the
   * additive inverse: P + (-P) = point at infinity.
   *
   * Use cases: subtraction of points (A - B = A + (-B)), cancellation
   * checks in zero-knowledge proofs.
   */
  public checkNegate(expectedNegY: bigint) {
    const neg = ecNegate(this.pt);
    assert(ecPointY(neg) === expectedNegY);
  }

  /**
   * Verify that negating a point twice returns the original point.
   *
   * This demonstrates the involution property: -(-P) = P. Double negation
   * is a no-op, which the compiler can optimize away at the ANF level.
   */
  public checkNegateRoundtrip() {
    const neg1 = ecNegate(this.pt);
    const neg2 = ecNegate(neg1);
    assert(ecPointX(neg2) === ecPointX(this.pt));
    assert(ecPointY(neg2) === ecPointY(this.pt));
  }

  // -------------------------------------------------------------------
  // Modular arithmetic
  // -------------------------------------------------------------------

  /**
   * Perform modular reduction and verify the result.
   *
   * `ecModReduce(value, mod)` computes `((value % mod) + mod) % mod`,
   * ensuring the result is always non-negative. This is essential for
   * EC group arithmetic where scalars must be in [0, n-1].
   *
   * Use cases: reducing Schnorr response values mod n, ensuring private
   * key scalars are in the valid range, hash-to-scalar conversion.
   */
  public checkModReduce(value: bigint, modulus: bigint, expected: bigint) {
    assert(ecModReduce(value, modulus) === expected);
  }

  // -------------------------------------------------------------------
  // Compressed encoding
  // -------------------------------------------------------------------

  /**
   * Compress the stored point to 33-byte public key format and verify.
   *
   * `ecEncodeCompressed(p)` produces a 33-byte encoding: a prefix byte
   * (0x02 if y is even, 0x03 if y is odd) followed by the 32-byte
   * x-coordinate. This is the standard Bitcoin compressed public key format.
   *
   * Use cases: generating public key hashes for P2PKH addresses, comparing
   * computed keys against stored key hashes, interoperating with standard
   * Bitcoin tooling.
   */
  public checkEncodeCompressed(expected: ByteString) {
    const compressed = ecEncodeCompressed(this.pt);
    assert(compressed === expected);
  }

  // -------------------------------------------------------------------
  // Algebraic properties
  // -------------------------------------------------------------------

  /**
   * Verify that scalar multiplication by 1 is the identity operation.
   *
   * For any point P: 1 * P = P. This is a fundamental algebraic property
   * and a useful sanity check that ecMul handles the identity scalar.
   */
  public checkMulIdentity() {
    const result = ecMul(this.pt, 1n);
    assert(ecPointX(result) === ecPointX(this.pt));
    assert(ecPointY(result) === ecPointY(this.pt));
  }

  /**
   * Verify that the result of ecAdd lies on the curve.
   *
   * Closure property: if A and B are on the curve, then A + B is also on
   * the curve. This is guaranteed by the group law but serves as a
   * correctness check for the EC addition implementation.
   */
  public checkAddOnCurve(other: Point) {
    const result = ecAdd(this.pt, other);
    assert(ecOnCurve(result));
  }

  /**
   * Verify that a generator multiplication result lies on the curve.
   *
   * For any scalar k, k * G must be a valid curve point. This tests the
   * ecMulGen implementation produces points satisfying the curve equation.
   */
  public checkMulGenOnCurve(scalar: bigint) {
    const result = ecMulGen(scalar);
    assert(ecOnCurve(result));
  }
}

import {
  SmartContract, assert,
  ecPointX, ecPointY, ecOnCurve, ecNegate, ecModReduce,
  ecAdd, ecMul, ecMulGen, ecMakePoint, ecEncodeCompressed,
} from 'runar-lang';
import type { Point } from 'runar-lang';

class ECPrimitives extends SmartContract {
  readonly pt: Point;

  constructor(pt: Point) {
    super(pt);
    this.pt = pt;
  }

  // Method 0: check x-coordinate extraction
  public checkX(expectedX: bigint) {
    assert(ecPointX(this.pt) === expectedX);
  }

  // Method 1: check y-coordinate extraction
  public checkY(expectedY: bigint) {
    assert(ecPointY(this.pt) === expectedY);
  }

  // Method 2: check point is on curve
  public checkOnCurve() {
    assert(ecOnCurve(this.pt));
  }

  // Method 3: check point negation
  public checkNegateY(expectedNegY: bigint) {
    const negated = ecNegate(this.pt);
    assert(ecPointY(negated) === expectedNegY);
  }

  // Method 4: check modular reduction
  public checkModReduce(value: bigint, modulus: bigint, expected: bigint) {
    assert(ecModReduce(value, modulus) === expected);
  }

  // Method 5: check point addition (this.pt + other)
  public checkAdd(other: Point, expectedX: bigint, expectedY: bigint) {
    const result = ecAdd(this.pt, other);
    assert(ecPointX(result) === expectedX);
    assert(ecPointY(result) === expectedY);
  }

  // Method 6: check scalar multiplication (this.pt * scalar)
  public checkMul(scalar: bigint, expectedX: bigint, expectedY: bigint) {
    const result = ecMul(this.pt, scalar);
    assert(ecPointX(result) === expectedX);
    assert(ecPointY(result) === expectedY);
  }

  // Method 7: check generator scalar multiplication (scalar * G)
  public checkMulGen(scalar: bigint, expectedX: bigint, expectedY: bigint) {
    const result = ecMulGen(scalar);
    assert(ecPointX(result) === expectedX);
    assert(ecPointY(result) === expectedY);
  }

  // Method 8: check make point roundtrip
  public checkMakePoint(x: bigint, y: bigint, expectedX: bigint, expectedY: bigint) {
    const point = ecMakePoint(x, y);
    assert(ecPointX(point) === expectedX);
    assert(ecPointY(point) === expectedY);
  }

  // Method 9: check compressed encoding
  public checkEncodeCompressed(expected: ByteString) {
    const compressed = ecEncodeCompressed(this.pt);
    assert(compressed === expected);
  }

  // Method 10: check ecMul with scalar=1 (identity — should return same point)
  public checkMulIdentity() {
    const result = ecMul(this.pt, 1n);
    assert(ecPointX(result) === ecPointX(this.pt));
    assert(ecPointY(result) === ecPointY(this.pt));
  }

  // Method 11: check negate roundtrip (negate twice should return original)
  public checkNegateRoundtrip() {
    const neg1 = ecNegate(this.pt);
    const neg2 = ecNegate(neg1);
    assert(ecPointX(neg2) === ecPointX(this.pt));
    assert(ecPointY(neg2) === ecPointY(this.pt));
  }

  // Method 12: check ecOnCurve on a computed point (ecAdd result is on curve)
  public checkAddOnCurve(other: Point) {
    const result = ecAdd(this.pt, other);
    assert(ecOnCurve(result));
  }

  // Method 13: check ecMulGen result is on curve
  public checkMulGenOnCurve(scalar: bigint) {
    const result = ecMulGen(scalar);
    assert(ecOnCurve(result));
  }
}

import {
  SmartContract, assert, len,
  ecAdd, ecMul, ecMulGen, ecNegate, ecOnCurve,
  ecEncodeCompressed, ecMakePoint, ecPointX, ecPointY,
} from 'runar-lang';
import type { ByteString } from 'runar-lang';

class ECUnit extends SmartContract {
    readonly pubKey: ByteString;
    constructor(pubKey: ByteString) {
        super(pubKey);
        this.pubKey = pubKey;
    }

    public testOps() {
        const g = ecMulGen(1n);
        assert(ecOnCurve(g));
        const neg = ecNegate(g);
        assert(ecOnCurve(neg));
        const doubled = ecMul(g, 2n);
        assert(ecOnCurve(doubled));
        const sum = ecAdd(g, g);
        assert(ecOnCurve(sum));
        // P + (-P) is the point at infinity, which affine x||y cannot encode:
        // ecAdd returns the all-zero blob from a SUCCESSFUL script (as does
        // ecMul for any k = 0 mod n). ecOnCurve is the only way to notice,
        // so it must reject it. Selecting the tangent on px == qx alone
        // returned 2G here instead: on-curve, plausible, and accepted.
        const infPt = ecAdd(g, neg);
        assert(!ecOnCurve(infPt));
        const x = ecPointX(g);
        const y = ecPointY(g);
        const rebuilt = ecMakePoint(x, y);
        assert(ecOnCurve(rebuilt));
        const compressed = ecEncodeCompressed(g);
        assert(len(compressed) == 33n);
        assert(true);
    }
}

import { SmartContract, assert, PubKey, Sig, checkSig } from 'runar-lang';

/**
 * Three-party escrow contract for marketplace payment protection.
 *
 * Holds funds in a UTXO until two parties jointly authorize a spend. The buyer
 * deposits funds by sending to this contract's locking script. Two spending
 * paths allow funds to move depending on the transaction outcome:
 *
 * - {@link release} — seller + arbiter both sign to release funds to the seller
 *   (e.g., goods delivered successfully).
 * - {@link refund}  — buyer + arbiter both sign to refund funds to the buyer
 *   (e.g., dispute resolved in buyer's favor).
 *
 * The arbiter serves as the trust anchor — no single party can act alone.
 * Both paths require two signatures (dual-sig), ensuring the arbiter must
 * co-sign every spend. This prevents unilateral action by either party.
 *
 * Script layout:
 *   Unlocking: <methodIndex> <sig1> <sig2>
 *   Locking:   OP_IF <seller checkSig> <arbiter checkSig>
 *              OP_ELSE <buyer checkSig> <arbiter checkSig> OP_ENDIF
 *
 * This is a stateless contract (`SmartContract`). The three public keys are
 * `readonly` constructor parameters baked into the locking script at deploy time.
 *
 * @param buyer   — buyer's compressed public key (33 bytes)
 * @param seller  — seller's compressed public key (33 bytes)
 * @param arbiter — arbiter's compressed public key (33 bytes)
 */
class Escrow extends SmartContract {
  readonly buyer: PubKey;
  readonly seller: PubKey;
  readonly arbiter: PubKey;

  constructor(buyer: PubKey, seller: PubKey, arbiter: PubKey) {
    super(buyer, seller, arbiter);
    this.buyer = buyer;
    this.seller = seller;
    this.arbiter = arbiter;
  }

  /**
   * Release escrowed funds to the seller.
   * Requires both the seller's and arbiter's signatures.
   */
  public release(sellerSig: Sig, arbiterSig: Sig) {
    assert(checkSig(sellerSig, this.seller));
    assert(checkSig(arbiterSig, this.arbiter));
  }

  /**
   * Refund escrowed funds to the buyer.
   * Requires both the buyer's and arbiter's signatures.
   */
  public refund(buyerSig: Sig, arbiterSig: Sig) {
    assert(checkSig(buyerSig, this.buyer));
    assert(checkSig(arbiterSig, this.arbiter));
  }
}

