    super();
  }

  public set00(v: bigint) {
    this.grid[0][0] = v;
    assert(true);
  }

  public set01(v: bigint) {
    this.grid[0][1] = v;
    assert(true);
  }

  public set10(v: bigint) {
    this.grid[1][0] = v;
    assert(true);
  }

  public set11(v: bigint) {
    this.grid[1][1] = v;
    assert(true);
  }

  public read00() {
    assert(this.grid[0][0] == this.grid[0][0]);
  }
}

