import { SmartContract, assert } from 'runar-lang';

/**
 * LoopShapes — the loop shape the corpus never had (R-102).
 *
 * The ANF `loop` node carries explicit `start` and `step` fields. Until this
 * example, the entire repository contained two `for` loops, both zero-start
 * and incrementing, so neither field was exercised — which is how Go's
 * constant folder came to drop `start` and `step` (N-128) and stay green.
 *
 * This contract closes the non-zero-start half of that gap and nothing more.
 * It holds exactly one loop, and that loop ascends:
 *
 *   loop 1 (i = 3n; i < 7n; i++):  3 + 4 + 5 + 6 = 18
 *
 * so `verify(seed)` asserts `seed + 18`.
 *
 * The descending half is still open: no fixture anywhere carries `step = -1`,
 * and three of the nine surfaces cannot spell a decrementing loop at all
 * (N-130), so that shape needs a fixture of its own rather than a second loop
 * bolted onto this one.
 */
export class LoopShapes extends SmartContract {
  readonly target: bigint;

  constructor(target: bigint) {
    super(target);
    this.target = target;
  }

  public verify(seed: bigint) {
    let acc: bigint = seed;
    for (let i = 3n; i < 7n; i++) {
      acc = acc + i;
    }
    assert(acc === this.target);
  }
}

import {
  StatefulSmartContract,
  assert,
  safediv,
  safemod,
  percentOf,
  clamp,
  sign,
  pow,
  sqrt,
  gcd,
  mulDiv,
  log2,
  abs,
  min,
  max,
  within,
  divmod,
  bool,
} from 'runar-lang';

/**
 * MathDemo — A stateful contract demonstrating every built-in math function
 * available in Rúnar.
 *
 * Bitcoin Script has limited native arithmetic (ADD, SUB, MUL, DIV, MOD).
 * Rúnar provides higher-level math functions that compile into sequences of
 * these primitives, enabling complex financial calculations on-chain.
 *
 * Each public method applies one math operation to the contract's stored
 * `value`, showing how these functions compile to pure Bitcoin Script.
 * All operations use integer math — no floating point.
 *
 * This contract is intentionally minimal: no signature checks are performed,
 * so any caller can invoke any method. In production, you would combine these
 * math operations with authentication logic.
 */
class MathDemo extends StatefulSmartContract {
  value: bigint;

  constructor(value: bigint) {
    super(value);
    this.value = value;
  }

  /**
   * Safe division — divides the stored value by `divisor`, asserting that
   * `divisor` is non-zero. The transaction fails if divisor is 0.
   *
   * Use cases: splitting payments, computing averages.
   */
  public divideBy(divisor: bigint) {
    this.value = safediv(this.value, divisor);
  }

  /**
   * Withdraw with a fee calculated in basis points (1 bps = 0.01%).
   * `percentOf(amount, feeBps)` computes `amount * feeBps / 10000`.
   * Asserts that the total (amount + fee) does not exceed the stored value.
   *
   * Use cases: fee calculation, royalties, commission deductions.
   */
  public withdrawWithFee(amount: bigint, feeBps: bigint) {
    const fee = percentOf(amount, feeBps);
    const total = amount + fee;
    assert(total <= this.value);
    this.value = this.value - total;
  }

  /**
   * Constrains the stored value to the range [lo, hi].
   * If value < lo, it becomes lo. If value > hi, it becomes hi.
   *
   * Use cases: enforcing min/max limits on bids, prices, or balances.
   */
  public clampValue(lo: bigint, hi: bigint) {
    this.value = clamp(this.value, lo, hi);
  }

  /**
   * Replaces the stored value with its sign: -1, 0, or 1.
   *
   * Use cases: direction detection, comparison results, branch selection.
   */
  public normalize() {
    this.value = sign(this.value);
  }

  /**
   * Raises the stored value to the power `exp` (integer exponentiation).
   *
   * Use cases: compound interest, polynomial evaluation.
   */
  public exponentiate(exp: bigint) {
    this.value = pow(this.value, exp);
  }

  /**
   * Replaces the stored value with its integer square root (floor).
   *
   * Use cases: geometric mean, distance calculations.
   */
  public squareRoot() {
    this.value = sqrt(this.value);
  }

  /**
   * Replaces the stored value with gcd(value, other) — the greatest
   * common divisor.
   *
   * Use cases: fraction simplification, coprimality checks.
   */
  public reduceGcd(other: bigint) {
    this.value = gcd(this.value, other);
  }

  /**
   * Computes `(value * numerator) / denominator` with intermediate precision
   * to avoid overflow. Replaces the stored value with the result.
   *
   * Use cases: currency conversion, proportional allocation, token swaps.
   */
  public scaleByRatio(numerator: bigint, denominator: bigint) {
    this.value = mulDiv(this.value, numerator, denominator);
  }

  /**
   * Replaces the stored value with floor(log2(value)) — the floor of the
   * base-2 logarithm.
   *
   * Use cases: bit-length calculation, binary search depth.
   */
  public computeLog2() {
    this.value = log2(this.value);
  }

  /**
   * Replaces the stored value with its absolute value.
   *
   * Use cases: magnitude comparison, distance calculation.
   */
  public makeAbs() {
    this.value = abs(this.value);
  }

  /**
   * Replaces the stored value with min(value, other).
   *
   * Use cases: capping bids, picking the smaller of two amounts.
   */
  public takeMin(other: bigint) {
    this.value = min(this.value, other);
  }

  /**
   * Replaces the stored value with max(value, other).
   *
   * Use cases: enforcing reserve floors, picking the larger of two amounts.
   */
  public takeMax(other: bigint) {
    this.value = max(this.value, other);
  }

  /**
   * Asserts that the stored value lies in the half-open range [lo, hi),
   * mirroring the semantics of Bitcoin Script's OP_WITHIN.
   *
   * Use cases: bounds-checked unlock parameters.
   */
  public assertWithin(lo: bigint, hi: bigint) {
    assert(within(this.value, lo, hi));
  }

  /**
   * Safe modulo — replaces the stored value with `value mod divisor`,
   * asserting that `divisor` is non-zero.
   *
   * Use cases: round-robin scheduling, modular index calculation.
   */
  public moduloBy(divisor: bigint) {
    this.value = safemod(this.value, divisor);
  }

  /**
   * Replaces the stored value with the quotient of `value / divisor`,
   * derived from Rúnar's `divmod` builtin that emits the canonical
   * OP_2DUP OP_DIV OP_ROT OP_ROT OP_MOD OP_DROP sequence.
   *
   * Use cases: integer division with a side-effect on the modulo result.
   */
  public divmodBy(divisor: bigint) {
    this.value = divmod(this.value, divisor);
  }

  /**
   * Asserts that the stored value is "truthy" (non-zero) using the
   * dedicated `bool` builtin, which compiles to OP_0NOTEQUAL.
   *
   * Use cases: terminal liveness check for non-zero state.
   */
  public assertNonZero() {
    assert(bool(this.value));
  }
}

import {
  SmartContract, assert,
  merkleRootSha256, merkleRootHash256,
} from 'runar-lang';
import type { ByteString } from 'runar-lang';

/**
 * MerkleProofDemo — Demonstrates Merkle proof verification in Bitcoin Script.
 *
 * Two built-in functions:
 * - merkleRootSha256(leaf, proof, index, depth) — SHA-256 Merkle root (STARK/FRI)
 * - merkleRootHash256(leaf, proof, index, depth) — Hash256 Merkle root (Bitcoin)
 *
 * Parameters:
 * - leaf: 32-byte leaf hash
 * - proof: concatenated 32-byte sibling hashes (depth * 32 bytes)
 * - index: leaf position (determines left/right at each level)
 * - depth: number of tree levels (MUST be a compile-time constant)
 *
 * The depth parameter is consumed at compile time — the loop is unrolled,
 * producing ~15 opcodes per level. No runtime iteration.
 */
class MerkleProofDemo extends SmartContract {
  readonly expectedRoot: ByteString;

  constructor(expectedRoot: ByteString) {
    super(expectedRoot);
    this.expectedRoot = expectedRoot;
  }

  /** Verify a SHA-256 Merkle proof at depth 4. */
  public verifySha256(leaf: ByteString, proof: ByteString, index: bigint) {
    const root = merkleRootSha256(leaf, proof, index, 4n);
    assert(root === this.expectedRoot);
  }

  /** Verify a Hash256 Merkle proof at depth 4. */
  public verifyHash256(leaf: ByteString, proof: ByteString, index: bigint) {
    const root = merkleRootHash256(leaf, proof, index, 4n);
    assert(root === this.expectedRoot);
  }
}

import { StatefulSmartContract, assert, checkSig } from 'runar-lang';
import type { PubKey, Sig, ByteString } from 'runar-lang';

/**
 * MessageBoard -- a stateful smart contract with a ByteString mutable state field.
 *
 * Demonstrates Runar's ByteString state management: a message that persists
 * and can be updated across spending transactions on the Bitcoin SV blockchain.
 *
 * Because this class extends {@link StatefulSmartContract} (not SmartContract),
 * the compiler automatically injects:
 *   - `checkPreimage` at each public method entry -- verifies the spending
 *     transaction matches the sighash preimage.
 *   - State continuation at each public method exit -- serializes updated
 *     state into the new output script.
 *
 * **Script layout (on-chain):**
 * ```
 * Locking: <contract logic> OP_RETURN <message> <owner>
 * ```
 * The state (`message`) is serialized as push data after OP_RETURN. The
 * `owner` is readonly and baked into the locking script. When spent,
 * the compiler-injected preimage check ensures the new output carries the
 * correct updated state.
 *
 * **Authorization:** The `post` method has no access control -- anyone can
 * update the message. The `burn` method requires the owner's signature to
 * permanently destroy the contract (no continuation output).
 *
 * @param message - The current message stored on-chain (mutable ByteString)
 * @param owner   - The contract owner's compressed public key (readonly)
 */
class MessageBoard extends StatefulSmartContract {
  /** The current message. Mutable -- updated via `post`. */
  message: ByteString;
  /** The contract owner's public key. Readonly -- baked into the locking script. */
  readonly owner: PubKey;

  constructor(message: ByteString, owner: PubKey) {
    super(message, owner);
    this.message = message;
    this.owner = owner;
  }

  /**
   * Post a new message, replacing the current one.
   * Anyone can call this method -- no signature required.
   */
  public post(newMessage: ByteString) {
    this.message = newMessage;
  }

  /**
   * Burn the contract -- terminal spend with no continuation output.
   * Only the owner can burn the contract (requires a valid signature).
   */
  public burn(sig: Sig) {
    assert(checkSig(sig, this.owner));
  }
}

import { SmartContract, assert, PubKey, Sig, checkSig } from 'runar-lang';

class MultiMethod extends SmartContract {
  readonly owner: PubKey;
  readonly backup: PubKey;

  constructor(owner: PubKey, backup: PubKey) {
    super(owner, backup);
    this.owner = owner;
    this.backup = backup;
  }

  private computeThreshold(a: bigint, b: bigint): bigint {
    return a * b + 1n;
  }

  public spendWithOwner(sig: Sig, amount: bigint): void {
    const threshold: bigint = this.computeThreshold(amount, 2n);
    assert(threshold > 10n);
    assert(checkSig(sig, this.owner));
  }

  public spendWithBackup(sig: Sig): void {
    assert(checkSig(sig, this.backup));
  }
}

import { SmartContract, assert, PubKey, Sig, checkMultiSig } from 'runar-lang';

/**
 * MultiSig2of3 — a 2-of-3 multi-signature contract.
 *
 * Funds are locked to three public keys. To spend, the unlocker must supply
 * two valid ECDSA signatures from any two of the committed keys. The signing
 * pair can be (pk1,pk2), (pk1,pk3), or (pk2,pk3); the order of the supplied
 * signatures must match the order of the corresponding pubkeys in the
 * committed array.
 *
 * ## Why this contract exists
 *
 * `checkMultiSig([sig1, sig2], [this.pk1, this.pk2, this.pk3])` lowers to two
 * `array_literal` ANF nodes — one for the signature array, one for the pubkey
 * array. This is the canonical site where `array_literal` is emitted and is
 * useful as a cross-compiler conformance fixture.
 *
 * ## Script layout
 *
 *   Unlocking: <sig1> <sig2>
 *   Locking:   OP_0 <sig1> <sig2> 2 <pk1> <pk2> <pk3> 3 OP_CHECKMULTISIG
 *              OP_VERIFY
 *
 * ## Parameter sizes
 *
 *   - pk1, pk2, pk3: 33 bytes each (compressed secp256k1 public keys)
 *   - sig1, sig2: ~72 bytes each (DER-encoded ECDSA signatures + sighash flag)
 */
class MultiSig2of3 extends SmartContract {
  readonly pk1: PubKey;
  readonly pk2: PubKey;
  readonly pk3: PubKey;

  constructor(pk1: PubKey, pk2: PubKey, pk3: PubKey) {
    super(pk1, pk2, pk3);
    this.pk1 = pk1;
    this.pk2 = pk2;
    this.pk3 = pk3;
  }

  /** Unlock requires two valid signatures from any two of the three committed pubkeys. */
  public unlock(sig1: Sig, sig2: Sig): void {
    assert(checkMultiSig([sig1, sig2], [this.pk1, this.pk2, this.pk3]));
  }
}

import { SmartContract, assert, substr, bin2num, num2bin, cat } from 'runar-lang';
import type { ByteString } from 'runar-lang';

/**
 * Regression test for issue #34 — cross-method parameter-name shadowing.
 *
 * The local `x: bigint` in `walk` must NOT inherit the byte type of the
 * `x: ByteString` parameter of `other`. Before the fix, the ANF param-type
 * lookup searched ALL methods' params, so `x` matched `other`'s parameter and
 * `1n + x` miscompiled to OP_CAT (byte concat, 0x7e) instead of OP_ADD (0x93),
 * making the compiled script diverge from the interpreter.
 */
class StackTrackerRepro extends SmartContract {
  constructor() { super(); }

  public walk(buf: ByteString, count: bigint, target: ByteString) {
    let p: bigint = 0n;
    let found: boolean = false;
    if (0n < count) {
      const x: bigint = bin2num(cat(substr(buf, p, 1n), num2bin(0n, 1n)));
      const blob: ByteString = substr(buf, p, 1n + x);
      if (blob === target) { found = true; }
      p = p + 1n + x;
    }
    assert(found || !found);
  }

  public other(x: ByteString) { assert(x === x); }
}

import { SmartContract, assert, PubKey, Sig, ByteString, RabinSig, RabinPubKey, checkSig, verifyRabinSig, num2bin } from 'runar-lang';

/**
 * OraclePriceFeed — A stateless oracle contract for price-triggered payouts.
 *
 * Demonstrates the "oracle pattern" where off-chain data (e.g., asset prices)
 * is cryptographically signed by a trusted oracle and verified on-chain using
 * Rabin signatures. Rabin signatures are well-suited for Bitcoin Script because
 * verification requires only modular multiplication and comparison — operations
 * that are cheap in Script.
 *
 * The contract enforces three verification layers:
 *   1. Oracle verification — the price was genuinely signed by the trusted oracle's Rabin key
 *   2. Price threshold — the price must exceed 50,000 (application-specific business logic)
 *   3. Receiver authorization — the receiver must provide a valid ECDSA signature to claim the payout
 *
 * Use cases: derivatives/futures settlement, price-triggered payouts, conditional
 * escrow based on market data, insurance contracts.
 *
 * Contract model: Stateless (SmartContract). The oracle's Rabin public key and the
 * receiver's ECDSA public key are immutable constructor parameters.
 */
class OraclePriceFeed extends SmartContract {
  /** Rabin public key of the trusted oracle (a large integer modulus, typically 128+ bytes). */
  readonly oraclePubKey: RabinPubKey;
  /** ECDSA compressed public key (33 bytes) of the authorized payout receiver. */
  readonly receiver: PubKey;

  constructor(oraclePubKey: RabinPubKey, receiver: PubKey) {
    super(oraclePubKey, receiver);
    this.oraclePubKey = oraclePubKey;
    this.receiver = receiver;
  }

  /**
   * Settle the contract by proving a price was signed by the oracle and exceeds
   * the threshold. The receiver must also sign to authorize the payout.
   *
   * @param price - The oracle-attested price value (integer).
   * @param rabinSig - Rabin signature produced by the oracle over the price (variable length).
   * @param padding - Rabin signature padding bytes required for verification (variable length).
   * @param sig - ECDSA signature (~72 bytes) from the receiver authorizing the spend.
   */
  public settle(price: bigint, rabinSig: RabinSig, padding: ByteString, sig: Sig) {
    // Layer 1: Oracle verification — convert the price to its 8-byte little-endian
    // canonical form (the format the oracle signs), then verify the Rabin signature
    // against the oracle's public key using modular arithmetic.
    const msg = num2bin(price, 8n);
    assert(verifyRabinSig(msg, rabinSig, padding, this.oraclePubKey));

    // Layer 2: Price threshold — application-specific business logic requiring
    // the oracle-attested price to exceed 50,000 before the payout is allowed.
    assert(price > 50000n);

    // Layer 3: Receiver authorization — the designated receiver must provide a
    // valid ECDSA signature to claim the payout, preventing front-running.
    assert(checkSig(sig, this.receiver));
  }
}

import { SmartContract, assert, Sig, PubKey, Addr, hash160, checkSig } from 'runar-lang';

/**
 * OrdinalNFT -- Pay-to-Public-Key-Hash lock for a 1sat ordinal inscription.
 *
 * This is a stateless P2PKH contract used to lock an ordinal NFT. The owner
 * (holder of the private key whose public key hashes to `pubKeyHash`) can
 * unlock and transfer the ordinal by providing a valid signature and public key.
 *
 * ## Ordinal Inscriptions
 *
 * A 1sat ordinal NFT is a UTXO carrying exactly 1 satoshi with an inscription
 * envelope embedded in the locking script. The inscription is a no-op
 * (OP_FALSE OP_IF ... OP_ENDIF) that doesn't affect script execution but
 * permanently records content (image, text, JSON, etc.) on-chain.
 *
 * The inscription envelope is injected by the SDK's `withInscription()` method
 * at deployment time -- the contract logic itself is just standard P2PKH.
 *
 * ## Script Layout
 *
 *   Unlocking: `<sig> <pubKey>`
 *   Locking:   `OP_DUP OP_HASH160 <pubKeyHash> OP_EQUALVERIFY OP_CHECKSIG [inscription envelope]`
 */
class OrdinalNFT extends SmartContract {
  readonly pubKeyHash: Addr;

  constructor(pubKeyHash: Addr) {
    super(pubKeyHash);
    this.pubKeyHash = pubKeyHash;
  }

  /** Unlock by proving ownership of the private key corresponding to pubKeyHash. */
  public unlock(sig: Sig, pubKey: PubKey) {
    assert(hash160(pubKey) === this.pubKeyHash);
    assert(checkSig(sig, pubKey));
  }
}

import { SmartContract, assert, p256Negate, p256EncodeCompressed } from 'runar-lang';
import type { P256Point, ByteString } from 'runar-lang';

/**
 * P256EncodeNegate — executed coverage for p256Negate and p256EncodeCompressed.
 *
 * Both builtins were among the 30 of runar-lang's 105 `export function`s that
 * appeared in ZERO fixtures' `expected-ir.json` and that the fuzzer cannot
 * generate. `p256-primitives` exercises Add / Mul / MulGen / OnCurve and stops
 * there, so seven compilers shipped negate and compress with no cross-tier
 * byte comparison and nothing that ever ran them.
 *
 * The compression half is not a minor omission. CL-BUG-095 was exactly here:
 * the parity byte used to be read from the blob's LAST byte rather than a
 * fixed offset, so appending one byte FLIPPED THE SIGN of the compressed
 * encoding — the same point compressed to 02‖x or 03‖x at the caller's
 * choice, and anything that hashes a compressed pubkey became forgeable
 * between the two spellings. The fix (verify the width, read parity from
 * offset 31 of y) had no fixture standing on it until this one.
 *
 * `conformance/p256_encode_negate_execution_test.go` spends this fixture's
 * real locking script against a P-256 implementation written independently in
 * Go, at the boundaries that matter:
 *
 *   negate      G and a derived point; the involution negate(negate(P)) == P;
 *               y == 0, where p - y must reduce back to 0 and not to p;
 *               a non-canonical coordinate (x == p, y == p), which the
 *               canonicity guard must refuse;
 *               a 65-byte and a 63-byte blob, which the width gate must refuse
 *   compress    the 02/03 prefix in BOTH parities, so a flipped parity bit
 *               cannot pass; the CL-BUG-095 shape itself — the same point
 *               with one byte appended, which must be REFUSED rather than
 *               compressed to the opposite prefix
 *
 * Measured, both builtins are correct at every one of those. The value here is
 * the gate, not a fix.
 */
class P256EncodeNegate extends SmartContract {
  readonly expectedCompressed: ByteString;

  constructor(expectedCompressed: ByteString) {
    super(expectedCompressed);
    this.expectedCompressed = expectedCompressed;
  }

  /** (x, y) -> (x, p - y). Guards coordinate canonicity AND the 64-byte width. */
  public checkNegate(p: P256Point, expected: P256Point): void {
    const n: P256Point = p256Negate(p);
    assert(n == expected);
  }

  /** Point -> 33-byte 02/03‖x. Guards the width; parity is read at a fixed offset. */
  public checkEncode(p: P256Point, expected: ByteString): void {
    const e: ByteString = p256EncodeCompressed(p);
    assert(e == expected);
  }

  /** Composed: compressing the negation must flip the prefix and nothing else. */
  public checkNegateThenEncode(p: P256Point): void {
    const n: P256Point = p256Negate(p);
    const e: ByteString = p256EncodeCompressed(n);
    assert(e == this.expectedCompressed);
  }
}

import { SmartContract, assert, p256Add, p256Mul, p256MulGen, p256OnCurve } from 'runar-lang';
import type { P256Point } from 'runar-lang';

class P256Primitives extends SmartContract {
  readonly expectedPoint: P256Point;

  constructor(expectedPoint: P256Point) {
    super(expectedPoint);
    this.expectedPoint = expectedPoint;
  }

  public verify(k: bigint, basePoint: P256Point) {
    const result: P256Point = p256Mul(basePoint, k);
    assert(p256OnCurve(result));
    assert(result == this.expectedPoint);
  }

  public verifyAdd(a: P256Point, b: P256Point) {
    const result: P256Point = p256Add(a, b);
    assert(p256OnCurve(result));
    assert(result == this.expectedPoint);
  }

  public verifyMulGen(k: bigint) {
    const result: P256Point = p256MulGen(k);
    assert(p256OnCurve(result));
    assert(result == this.expectedPoint);
  }
}

import { SmartContract, assert, hash160, checkSig, verifyECDSA_P256 } from 'runar-lang';
import type { ByteString, Sig, PubKey, Addr } from 'runar-lang';

/**
 * Hybrid secp256k1 + P-256 wallet.
 *
 * ## Security Model: Two-Layer Authentication
 *
 * This contract binds a spend to two independent keys:
 *
 * 1. **secp256k1 OP_CHECKSIG** proves the signature commits to this specific
 *    transaction (via the Bitcoin sighash preimage).
 * 2. **P-256 ECDSA** verifies the secp256k1 sig bytes — proving the transaction
 *    was also authorized by the P-256 (NIST / Web PKI) key holder.
 *
 * The secp256k1 sig bytes ARE the message that P-256 signs. This means a
 * hardware security module or browser WebAuthn key (which speaks P-256) can
 * gate Bitcoin spending without any new opcode.
 *
 * ## Locking Script Layout
 *
 * ```
 * Unlocking: <p256Sig(64B)> <p256PubKey(33B)> <ecdsaSig(~72B)> <ecdsaPubKey(33B)>
 *
 * Locking:
 *   // --- secp256k1 verification (P2PKH) ---
 *   OP_OVER OP_TOALTSTACK           // copy ecdsaSig to alt stack for P-256 later
 *   OP_DUP OP_HASH160 <ecdsaPubKeyHash(20B)> OP_EQUALVERIFY OP_CHECKSIG OP_VERIFY
 *   // --- P-256 pubkey commitment ---
 *   OP_DUP OP_HASH160 <p256PubKeyHash(20B)> OP_EQUALVERIFY
 *   // --- P-256 verification ---
 *   OP_FROMALTSTACK OP_ROT OP_ROT   // bring ecdsaSig back as P-256 message
 *   <verifyECDSA_P256 inline>        // verify P256(ecdsaSig, p256Sig, p256PubKey)
 * ```
 *
 * ## Parameter Sizes
 *
 * - ecdsaPubKeyHash: 20 bytes (HASH160 of compressed secp256k1 public key)
 * - p256PubKeyHash: 20 bytes (HASH160 of 33-byte compressed P-256 public key)
 * - ecdsaSig: ~72 bytes (DER-encoded secp256k1 signature + sighash flag)
 * - ecdsaPubKey: 33 bytes (compressed secp256k1 public key)
 * - p256Sig: 64 bytes (raw r[32] || s[32] P-256 signature)
 * - p256PubKey: 33 bytes (compressed P-256 public key)
 */
class P256Wallet extends SmartContract {
  readonly ecdsaPubKeyHash: Addr;
  readonly p256PubKeyHash: ByteString;

  constructor(ecdsaPubKeyHash: Addr, p256PubKeyHash: ByteString) {
    super(ecdsaPubKeyHash, p256PubKeyHash);
    this.ecdsaPubKeyHash = ecdsaPubKeyHash;
    this.p256PubKeyHash = p256PubKeyHash;
  }

  public spend(p256Sig: ByteString, p256PubKey: ByteString, sig: Sig, pubKey: PubKey) {
    // Step 1: Verify secp256k1 — proves sig commits to this transaction
    assert(hash160(pubKey) === this.ecdsaPubKeyHash);
    assert(checkSig(sig, pubKey));

    // Step 2: Verify P-256 — proves secp256k1 sig was authorized by P-256 key
    assert(hash160(p256PubKey) === this.p256PubKeyHash);
    assert(verifyECDSA_P256(sig, p256Sig, p256PubKey));
  }
}

import { SmartContract, assert, PubKey, Sig, Addr, hash160, checkSig } from 'runar-lang';

/**
 * P2PKH — Pay-to-Public-Key-Hash.
 *
 * The most fundamental Bitcoin spending pattern. Funds are locked to the
 * HASH160 (SHA-256 → RIPEMD-160) of a public key. To spend, the recipient
 * must provide their full public key (which must hash to the stored hash)
 * and a valid ECDSA signature over the transaction.
 *
 * ## How It Works: Two-Step Verification
 *
 *  1. **Hash check** — `hash160(pubKey) === pubKeyHash` proves the provided
 *     public key matches the one committed to when the output was created.
 *  2. **Signature check** — `checkSig(sig, pubKey)` proves the spender
 *     holds the private key corresponding to that public key.
 *
 * This is the same pattern as standard Bitcoin P2PKH transactions, but
 * expressed in the Rúnar smart contract language.
 *
 * ## Script Layout
 *
 *   Unlocking: `<sig> <pubKey>`
 *   Locking:   `OP_DUP OP_HASH160 <pubKeyHash> OP_EQUALVERIFY OP_CHECKSIG`
 *
 * ## Parameter Sizes
 *
 *   - pubKeyHash: 20 bytes (HASH160 of compressed public key)
 *   - sig: ~72 bytes (DER-encoded ECDSA signature + sighash flag)
 *   - pubKey: 33 bytes (compressed secp256k1 public key)
 */
class P2PKH extends SmartContract {
  readonly pubKeyHash: Addr;

  constructor(pubKeyHash: Addr) {
    super(pubKeyHash);
    this.pubKeyHash = pubKeyHash;
  }

  /** Unlock verifies the pubKey hashes to the committed hash, then checks the signature. */
  public unlock(sig: Sig, pubKey: PubKey) {
    // Step 1: Verify pubKey matches the committed hash
    assert(hash160(pubKey) === this.pubKeyHash);
    // Step 2: Verify ECDSA signature proves ownership of the private key
    assert(checkSig(sig, pubKey));
  }
}

