  readonly ecdsaPubKeyHash: Addr;
  readonly p384PubKeyHash: ByteString;

  constructor(ecdsaPubKeyHash: Addr, p384PubKeyHash: ByteString) {
    super(ecdsaPubKeyHash, p384PubKeyHash);
