import { StatefulSmartContract, assert } from 'runar-lang';

/**
 * PropertyShadow — N-016 conformance fixture.
 *
 * Each property is read (and `count` written) AFTER a local of the same name
 * is declared. `this.target` / `this.count` must still mean the PROPERTY
 * (user decision R8: correct scoping). Before N-016 every tier resolved the
 * property read to the same-named local's stack slot, so
 * `assert(target == this.target)` compiled to OP_DUP OP_NUMEQUAL — always
 * true — and `this.count + count` doubled the local instead of reading state.
 */
class PropertyShadow extends StatefulSmartContract {
  readonly target: bigint;
  count: bigint;

  constructor(target: bigint, count: bigint) {
    super(target, count);
    this.target = target;
    this.count = count;
  }

  public bump(n: bigint) {
    const target = n + 1n;
    assert(target == this.target);
    const count = n;
    this.count = this.count + count;
    assert(this.count > count);
  }
}

import {
  SmartContract,
  assert,
  cat,
  checkPreimage,
  checkSig,
  hash160,
  len,
  substr,
  sha256,
  toByteString,
  verifyECDSA_P256,
} from 'runar-lang';
import type {
  Addr,
  ByteString,
  PubKey,
  Sig,
  SigHashPreimage,
} from 'runar-lang';

/**
 * R1-K1 Wallet -- hardware-backed primary spending with mnemonic recovery.
 *
 * Two independent keys can spend an output:
 *
 * 1. `spendR1` is the normal path. A NIST P-256 / secp256r1 key signs the
 *    current transaction's BIP-143 sighash. This key can be generated inside
 *    a YubiKey PIV slot so its private component never leaves the device.
 * 2. `recoverK1` is the backup path. A secp256k1 key authorizes an ordinary
 *    Bitcoin signature and can be restored from an offline mnemonic and
 *    passphrase if the YubiKey is lost.
 *
 * The R1 commitment is salted per output as
 * `HASH160(compressedR1PubKey || r1Salt)`. Only the commitment is placed in
 * the locking script; the unique high-entropy salt is supplied with the R1
 * unlocking witness. This prevents passive observers from linking unspent
 * outputs that reuse the same R1 key. The K1 constructor value is an ordinary
 * HASH160 commitment. A public key is revealed only when its path is used.
 *
 * R1 signing protocol:
 *
 *   sighash = SHA256(SHA256(txPreimage))
 *
 * The contract computes the first SHA-256 explicitly, and
 * `verifyECDSA_P256` applies the second SHA-256 internally. The YubiKey PIV
 * application receives `sighash` as its 32-byte ECCP256 digest and returns a
 * DER ECDSA signature, which the caller converts to 64-byte `r || s` form.
 * `checkPreimage` binds the supplied preimage to the actual transaction, while
 * the 0x41 pin requires SIGHASH_ALL | SIGHASH_FORKID.
 */
class R1K1Wallet extends SmartContract {
  /** HASH160 of the compressed 33-byte P-256 public key and a private salt. */
  readonly r1SaltedPubKeyHash: Addr;

  /** HASH160 of the compressed 33-byte secp256k1 recovery public key. */
  readonly k1PubKeyHash: Addr;

  constructor(r1SaltedPubKeyHash: Addr, k1PubKeyHash: Addr) {
    super(r1SaltedPubKeyHash, k1PubKeyHash);
    this.r1SaltedPubKeyHash = r1SaltedPubKeyHash;
    this.k1PubKeyHash = k1PubKeyHash;
  }

  /**
   * Normal spend using a hardware-backed P-256 signature.
   *
   * @param r1Sig       Raw 64-byte P-256 signature (`r[32] || s[32]`).
   * @param r1PubKey    Compressed 33-byte P-256 public key.
   * @param r1Salt      Private, unique per-output salt committed at locking.
   * @param txPreimage  BIP-143 preimage for the current transaction input.
   */
  public spendR1(
    r1Sig: ByteString,
    r1PubKey: ByteString,
    r1Salt: ByteString,
    txPreimage: SigHashPreimage,
  ) {
    assert(len(r1Salt) === 32n);
    assert(hash160(cat(r1PubKey, r1Salt)) === this.r1SaltedPubKeyHash);
    assert(substr(txPreimage, len(txPreimage) - 4n, 4n) === toByteString('41000000'));
    assert(checkPreimage(txPreimage));

    // verifyECDSA_P256 hashes its message once. Passing SHA256(preimage)
    // therefore verifies the YubiKey signature over HASH256(preimage), the
    // same transaction digest bound by checkPreimage.
    assert(verifyECDSA_P256(sha256(txPreimage), r1Sig, r1PubKey));
  }

  /**
   * Emergency recovery using the mnemonic-derived secp256k1 key.
   *
   * This path is intentionally independent of the YubiKey. Possession of the
   * recovery key is sufficient to spend, so its mnemonic and passphrase must
   * remain offline and separately protected.
   */
  public recoverK1(k1Sig: Sig, k1PubKey: PubKey) {
    assert(hash160(k1PubKey) === this.k1PubKeyHash);
    assert(checkSig(k1Sig, k1PubKey));
  }
}

import {
  SmartContract, assert, within,
  ecAdd, ecMul, ecMulGen, ecPointX, ecPointY, ecOnCurve, ecModReduce,
  hash256, cat, bin2num,
} from 'runar-lang';
import type { Point } from 'runar-lang';

/**
 * Schnorr Zero-Knowledge Proof verifier (non-interactive, Fiat-Shamir).
 *
 * Proves knowledge of a private key `k` such that `P = k*G` without
 * revealing `k`. Uses the Schnorr identification protocol with the
 * Fiat-Shamir heuristic to derive the challenge on-chain:
 *
 *   Prover: picks random r, computes R = r*G
 *   Challenge: e = bin2num(hash256(R || P))  (derived on-chain)
 *   Prover: sends s = r + e*k (mod n)
 *   Verifier: checks s*G === R + e*P
 *
 * The challenge is derived deterministically from the commitment and
 * public key, preventing the prover from choosing a convenient e.
 *
 * WARNING — this is a proof of KNOWLEDGE, not a spend authorization, and it
 * is REPLAYABLE. The challenge e = hash256(R || P) binds the witness to the
 * commitment and public key but NOT to the spending transaction. A valid
 * (rPoint, s) pair is therefore a bearer credential: once it appears on-chain,
 * any observer can replay the same (rPoint, s) to satisfy any other UTXO that
 * carries an identical `SchnorrZKP` locking script (same `pubKey`). Do NOT use
 * this contract as a standalone spend gate. To bind a proof to a particular
 * spend, fold the sighash/preimage into the challenge
 * (e = hash256(R || P || sighash)) so a witness is valid for exactly one tx.
 *
 * WARNING — nonce reuse is fatal. The contract verifies a single
 * non-interactive proof; it cannot detect that two proofs (sig1, sig2)
 * over different challenges (e1, e2) reuse the same nonce r. When a
 * prover reuses r across two proofs the secret key is recoverable by
 * any observer as k = (e1 - e2)^{-1} * (s1 - s2) mod n. The prover MUST
 * sample a fresh, uniformly random r for every proof. This is a
 * use-the-API-correctly responsibility of the proof generator; see
 * SchnorrZKP.test.ts ("nonce reuse off-chain key recovery") for the
 * canonical demonstration.
 */
class SchnorrZKP extends SmartContract {
  readonly pubKey: Point;

  constructor(pubKey: Point) {
    super(pubKey);
    this.pubKey = pubKey;
  }

  /**
   * Verify a Schnorr ZKP proof.
   *
   * @param rPoint - The commitment R = r*G (prover's nonce point)
   * @param s      - The response s = r + e*k (mod n)
   */
  public verify(rPoint: Point, s: bigint) {
    // Bound s to the canonical range [1, n) where n is the secp256k1 group
    // order. EC scalars are intentionally not reduced mod n inside the
    // primitives (k*G == (k + n)*G), so without this bound `s` and `s + n`
    // would both verify, opening a malleability surface where any forwarded
    // valid proof can be silently rewritten. The group order is inlined
    // here as a decimal literal so every frontend (sol/move/go/rust/zig all
    // lex `0x...` as a ByteString literal, not a bigint) lowers it to the
    // same `bigint_literal` ANF node and produces byte-identical hex.
    // Value: 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
    assert(within(
      s,
      1n,
      115792089237316195423570985008687907852837564279074904382605163141518161494337n,
    ));

    // Verify R is on the curve
    assert(ecOnCurve(rPoint));

    // Derive challenge via Fiat-Shamir: e = bin2num(hash256(R || P))
    const e = bin2num(hash256(cat(rPoint, this.pubKey)));

    // Left side: s*G
    const sG = ecMulGen(s);

    // Right side: R + e*P
    const eP = ecMul(this.pubKey, e);
    const rhs = ecAdd(rPoint, eP);

    // Verify equality
    assert(ecPointX(sG) === ecPointX(rhs));
    assert(ecPointY(sG) === ecPointY(rhs));
  }
}

