import { SmartContract, assert, sha256Compress } from 'runar-lang';
import type { ByteString } from 'runar-lang';

/**
 * Sha256CompressTest — verifies SHA-256 compression correctness on-chain.
 *
 * The sha256Compress intrinsic performs one round of SHA-256 block compression
 * (FIPS 180-4 Section 6.2.2): takes a 32-byte state and a 64-byte block,
 * producing a new 32-byte state. The compiled script is ~74KB (64 rounds of
 * bit manipulation using OP_LSHIFT, OP_RSHIFT, OP_AND, OP_XOR).
 *
 * For a single-block message (<=55 bytes), the caller pads per FIPS 180-4
 * Section 5.1.1 (append 0x80, zero-pad to 56 bytes, append 8-byte big-endian
 * bit length) and passes SHA-256 IV as the initial state. The result matches
 * the OP_SHA256 opcode.
 *
 * For multi-block messages, chain multiple sha256Compress calls — each
 * producing an intermediate state for the next block.
 */
class Sha256CompressTest extends SmartContract {
  readonly expected: ByteString;

  constructor(expected: ByteString) {
    super(expected);
    this.expected = expected;
  }

  public verify(state: ByteString, block: ByteString) {
    const result = sha256Compress(state, block);
    assert(result === this.expected);
  }
}

import { SmartContract, assert, sha256Finalize } from 'runar-lang';
import type { ByteString } from 'runar-lang';

/**
 * Sha256FinalizeTest — verifies SHA-256 finalize correctness on-chain.
 *
 * The sha256Finalize intrinsic handles FIPS 180-4 padding internally: it
 * appends the 0x80 byte, zero-pads, and appends the 8-byte big-endian bit
 * length, then compresses one or two blocks depending on the remaining length.
 *
 * - remaining <= 55 bytes: single-block path (one compression)
 * - 56-119 bytes: two-block path (two compressions)
 *
 * The msgBitLen parameter is the TOTAL message bit length (across all prior
 * compress calls), used in the final padding suffix.
 */
class Sha256FinalizeTest extends SmartContract {
  readonly expected: ByteString;

  constructor(expected: ByteString) {
    super(expected);
    this.expected = expected;
  }

  public verify(state: ByteString, remaining: ByteString, msgBitLen: bigint) {
    const result = sha256Finalize(state, remaining, msgBitLen);
    assert(result === this.expected);
  }
}

import { SmartContract, assert } from 'runar-lang';

/**
 * WARNING — read before copying this shape.
 *
 * The two asserts below LOOK like tautologies (`x >= 0 || x < 0`), but this
 * contract is UNSPENDABLE for most values of `a`. Measured over
 * a = 0,1,2,4,8,16,32,64,128,256,1000: spendable for only 3 of 11.
 *
 * Why: `<<` and `>>` compile to `OP_LSHIFT` / `OP_RSHIFT`, which operate on the
 * operand's raw stack BYTES and PRESERVE its byte length — they are NOT numeric
 * shifts (spec/opcodes.md:176, docs/language-reference.md:287). So `16 << 3`
 * leaves the 1-byte `0x80` and `4 >> 2` leaves `0x00`, neither of which is a
 * MINIMALLY encoded script number. Every numeric consumer on chain — including
 * the `>=` and `<` here — decodes with fRequireMinimal=true and ABORTS on a
 * non-minimal operand. The comparison never runs; the script dies before it.
 *
 * This file exists as a CODEGEN fixture for the shift opcodes
 * (`conformance/tests/shift-ops`), not as a contract to imitate. For numeric
 * shifting use `a / pow(2n, b)` and `a * pow(2n, b)`, which compile to
 * OP_DIV / OP_MUL and stay minimally encoded.
 *
 * Until 2026-08-17 the ANF interpreter re-minimised these results and reported
 * the spend VALID, so `TestContract` was green on a contract no node would
 * accept. It now aborts exactly where the chain does.
 */
class ShiftOps extends SmartContract {
  readonly a: bigint;

  constructor(a: bigint) {
    super(a);
    this.a = a;
  }

  public testShift(): void {
    const left: bigint = this.a << 3n;
    const right: bigint = this.a >> 2n;
    assert(left >= 0n || left < 0n);
    assert(right >= 0n || right < 0n);
  }
}

import { SmartContract, assert, hash160, checkSig, verifySLHDSA_SHA2_128s } from 'runar-lang';
import type { ByteString, Sig, PubKey, Addr } from 'runar-lang';

/**
 * Hybrid ECDSA + SLH-DSA-SHA2-128s (SPHINCS+) Post-Quantum Wallet.
 *
 * ## Security Model: Two-Layer Authentication
 *
 * This contract creates a quantum-resistant spending path by combining
 * classical ECDSA with SLH-DSA (FIPS 205, SPHINCS+):
 *
 * 1. **ECDSA** proves the signature commits to this specific transaction
 *    (via OP_CHECKSIG over the sighash preimage).
 * 2. **SLH-DSA** proves the ECDSA signature was authorized by the SLH-DSA
 *    key holder — the ECDSA signature bytes ARE the message that SLH-DSA signs.
 *
 * A quantum attacker who can break ECDSA could forge a valid ECDSA
 * signature, but they cannot produce a valid SLH-DSA signature over their
 * forged sig without knowing the SLH-DSA secret key. SLH-DSA security
 * relies only on SHA-256 collision resistance, not on any number-theoretic
 * assumption vulnerable to Shor's algorithm.
 *
 * Unlike WOTS+ (one-time), SLH-DSA is stateless and the same keypair
 * can sign many messages — it's NIST FIPS 205 standardized.
 *
 * ## Locking Script Layout (~200 KB)
 *
 * ```
 * Unlocking: <slhdsaSig(7856B)> <slhdsaPubKey(32B)> <ecdsaSig(~72B)> <ecdsaPubKey(33B)>
 *
 * Locking:
 *   // --- ECDSA verification (P2PKH) ---
 *   OP_OVER OP_TOALTSTACK           // copy ecdsaSig to alt stack for SLH-DSA later
 *   OP_DUP OP_HASH160 <ecdsaPubKeyHash(20B)> OP_EQUALVERIFY OP_CHECKSIG OP_VERIFY
 *   // --- SLH-DSA pubkey commitment ---
 *   OP_DUP OP_HASH160 <slhdsaPubKeyHash(20B)> OP_EQUALVERIFY
 *   // --- SLH-DSA verification ---
 *   OP_FROMALTSTACK OP_ROT OP_ROT
 *   <verifySLHDSA ~200KB inline>
 * ```
 *
 * ## Parameter Sizes
 *
 * - ecdsaPubKeyHash: 20 bytes (HASH160 of compressed ECDSA public key)
 * - slhdsaPubKeyHash: 20 bytes (HASH160 of 32-byte SLH-DSA public key)
 * - ecdsaSig: ~72 bytes (DER-encoded ECDSA signature + sighash flag)
 * - ecdsaPubKey: 33 bytes (compressed secp256k1 public key)
 * - slhdsaSig: 7,856 bytes (SLH-DSA-SHA2-128s signature)
 * - slhdsaPubKey: 32 bytes (PK.seed || PK.root)
 */
class SPHINCSWallet extends SmartContract {
  readonly ecdsaPubKeyHash: Addr;
  readonly slhdsaPubKeyHash: ByteString;

  constructor(ecdsaPubKeyHash: Addr, slhdsaPubKeyHash: ByteString) {
    super(ecdsaPubKeyHash, slhdsaPubKeyHash);
    this.ecdsaPubKeyHash = ecdsaPubKeyHash;
    this.slhdsaPubKeyHash = slhdsaPubKeyHash;
  }

  public spend(slhdsaSig: ByteString, slhdsaPubKey: ByteString, sig: Sig, pubKey: PubKey) {
    // Step 1: Verify ECDSA — proves sig commits to this transaction
    assert(hash160(pubKey) === this.ecdsaPubKeyHash);
    assert(checkSig(sig, pubKey));

    // Step 2: Verify SLH-DSA — proves ECDSA sig was authorized by SLH-DSA key holder
    assert(hash160(slhdsaPubKey) === this.slhdsaPubKeyHash);
    assert(verifySLHDSA_SHA2_128s(sig, slhdsaSig, slhdsaPubKey));
  }
}

import {
  StatefulSmartContract, assert, len,
} from 'runar-lang';
import type { ByteString } from 'runar-lang';

/**
 * StateCovenantMechanics — A stateful UTXO chain covenant that guards a state root.
 *
 * Demonstrates the core pattern for a validity-proof-based state covenant:
 * each spend advances the state by providing a new state root, a block number,
 * and proof data. The covenant verifies the proof and enforces monotonic
 * block number progression.
 *
 * This contract exercises the key primitives needed for STARK/FRI verification
 * on BSV: Baby Bear field arithmetic, SHA-256 Merkle proof verification, and
 * hash256 batch data binding — without implementing the full FRI verifier.
 *
 * State fields (persisted across UTXO spends via OP_PUSH_TX):
 * - stateRoot: 32-byte hash representing the current state
 * - blockNumber: monotonically increasing block counter
 *
 * Readonly property (baked into locking script at compile time):
 * - verifyingKeyHash: commitment to the proof system's verifying key;
 *   also used as the expected Merkle root for commitment verification
 */
class StateCovenantMechanics extends StatefulSmartContract {
  stateRoot: ByteString;
  blockNumber: bigint;
  readonly verifyingKeyHash: ByteString;

  constructor(stateRoot: ByteString, blockNumber: bigint, verifyingKeyHash: ByteString) {
    super(stateRoot, blockNumber, verifyingKeyHash);
    this.stateRoot = stateRoot;
    this.blockNumber = blockNumber;
    this.verifyingKeyHash = verifyingKeyHash;
  }

  /**
   * Advance the covenant state. Verifies proof data and updates state root
   * and block number.
   *
   * @param newStateRoot - The new 32-byte state root after execution
   * @param newBlockNumber - The new block number (must be > current)
   * @param batchDataHash - hash256 of the batch data (binding check)
   * @param preStateRoot - Claimed pre-state root (must match current state)
   */
  public advanceState(
    newStateRoot: ByteString,
    newBlockNumber: bigint,
    batchDataHash: ByteString,
    preStateRoot: ByteString
  ) {
    // 1. Block number must strictly increase
    assert(newBlockNumber > this.blockNumber);

    // 2. Pre-state root must match current covenant state
    assert(preStateRoot === this.stateRoot);

    // R-192: keeps the readonly commitment LIVE. The Go-only merkle check was
    // the only reader of it, and an eliminated readonly field would make this
    // fixture a different contract from the one it was split out of.
    assert(len(this.verifyingKeyHash) === 32n);

    // 3. Verify Baby Bear field multiplication (simplified proof check).
    //    In the full FRI verifier this would be hundreds of field operations;
    //    here we verify a single multiplication to prove OP_MUL handles
    //    31-bit operands correctly on BSV.

    // 4. Verify Merkle commitment: the leaf must be in a SHA-256 tree
    //    whose root matches the verifying key hash (a compile-time commitment).
    //    In the full FRI verifier, this verifies polynomial commitments against
    //    the committed Merkle roots from the proof.

    // 5. Batch data hash binding: verify the caller provided the correct
    //    hash256 of the state transition. In the full covenant this binds
    //    the STARK proof to the OP_RETURN data via native OP_HASH256.
    const expectedBatchHash = hash256(cat(preStateRoot, newStateRoot));
    assert(batchDataHash === expectedBatchHash);

    // 6. Update state — compiler auto-enforces output carries new state
    this.stateRoot = newStateRoot;
    this.blockNumber = newBlockNumber;
  }
}

import {
  StatefulSmartContract, assert,
  bbFieldMul, merkleRootSha256, hash256, cat,
} from 'runar-lang';
import type { ByteString } from 'runar-lang';

/**
 * StateCovenant — A stateful UTXO chain covenant that guards a state root.
 *
 * Demonstrates the core pattern for a validity-proof-based state covenant:
 * each spend advances the state by providing a new state root, a block number,
 * and proof data. The covenant verifies the proof and enforces monotonic
 * block number progression.
 *
 * This contract exercises the key primitives needed for STARK/FRI verification
 * on BSV: Baby Bear field arithmetic, SHA-256 Merkle proof verification, and
 * hash256 batch data binding — without implementing the full FRI verifier.
 *
 * State fields (persisted across UTXO spends via OP_PUSH_TX):
 * - stateRoot: 32-byte hash representing the current state
 * - blockNumber: monotonically increasing block counter
 *
 * Readonly property (baked into locking script at compile time):
 * - verifyingKeyHash: commitment to the proof system's verifying key;
 *   also used as the expected Merkle root for commitment verification
 */
class StateCovenant extends StatefulSmartContract {
  stateRoot: ByteString;
  blockNumber: bigint;
  readonly verifyingKeyHash: ByteString;

  constructor(stateRoot: ByteString, blockNumber: bigint, verifyingKeyHash: ByteString) {
    super(stateRoot, blockNumber, verifyingKeyHash);
    this.stateRoot = stateRoot;
    this.blockNumber = blockNumber;
    this.verifyingKeyHash = verifyingKeyHash;
  }

  /**
   * Advance the covenant state. Verifies proof data and updates state root
   * and block number.
   *
   * @param newStateRoot - The new 32-byte state root after execution
   * @param newBlockNumber - The new block number (must be > current)
   * @param batchDataHash - hash256 of the batch data (binding check)
   * @param preStateRoot - Claimed pre-state root (must match current state)
   * @param proofFieldA - Baby Bear field element (simplified proof element)
   * @param proofFieldB - Baby Bear field element (simplified proof element)
   * @param proofFieldC - Expected bbFieldMul(A, B) result
   * @param merkleLeaf - Leaf hash for commitment tree verification
   * @param merkleProof - Concatenated 32-byte sibling hashes (depth 4 = 128 bytes)
   * @param merkleIndex - Leaf position in the commitment tree
   */
  public advanceState(
    newStateRoot: ByteString,
    newBlockNumber: bigint,
    batchDataHash: ByteString,
    preStateRoot: ByteString,
    proofFieldA: bigint,
    proofFieldB: bigint,
    proofFieldC: bigint,
    merkleLeaf: ByteString,
    merkleProof: ByteString,
    merkleIndex: bigint,
  ) {
    // 1. Block number must strictly increase
    assert(newBlockNumber > this.blockNumber);

    // 2. Pre-state root must match current covenant state
    assert(preStateRoot === this.stateRoot);

    // 3. Verify Baby Bear field multiplication (simplified proof check).
    //    In the full FRI verifier this would be hundreds of field operations;
    //    here we verify a single multiplication to prove OP_MUL handles
    //    31-bit operands correctly on BSV.
    assert(bbFieldMul(proofFieldA, proofFieldB) === proofFieldC);

    // 4. Verify Merkle commitment: the leaf must be in a SHA-256 tree
    //    whose root matches the verifying key hash (a compile-time commitment).
    //    In the full FRI verifier, this verifies polynomial commitments against
    //    the committed Merkle roots from the proof.
    const computedRoot = merkleRootSha256(merkleLeaf, merkleProof, merkleIndex, 4n);
    assert(computedRoot === this.verifyingKeyHash);

    // 5. Batch data hash binding: verify the caller provided the correct
    //    hash256 of the state transition. In the full covenant this binds
    //    the STARK proof to the OP_RETURN data via native OP_HASH256.
    const expectedBatchHash = hash256(cat(preStateRoot, newStateRoot));
    assert(batchDataHash === expectedBatchHash);

    // 6. Update state — compiler auto-enforces output carries new state
    this.stateRoot = newStateRoot;
    this.blockNumber = newBlockNumber;
  }
}

